content_list.content:
জয়শ্রীরাম, আপনার `onuronOS` এবং `alap-framework` রিপোজিটরি বিশ্লেষণ করে আমি বুঝতে পেরেছি যে আপনি একটি অত্যন্ত সুপরিকল্পিত ইকোসিস্টেম তৈরি করছেন। যেহেতু `alap-framework`-এর টুলচেইন মূলত **Go** (৯৭.৬%) এবং **C** (২.৪%) দিয়ে তৈরি এবং `onuronOS`-এর ইউজারস্পেস **Rust**-এ, তাই **Nilang (NilLang)**-এর কম্পাইলার টুলচেইন Go-তে তৈরি করা সবচেয়ে যৌক্তিক এবং সামঞ্জস্যপূর্ণ সিদ্ধান্ত। 

একটি পূর্ণাঙ্গ প্রোগ্রামিং ল্যাঙ্গুয়েজ এক রাতে তৈরি হয় না, কিন্তু আমি আপনাকে একটি **প্রোডাকশন-গ্রেড ব্লুপ্রিন্ট** দিচ্ছি, যার মধ্যে **কোর কম্পাইলার কোড (Lexer + Parser)**, **গিটহাব/VS Code ইন্টিগ্রেশন**, এবং **ডকুমেন্টেশন স্ট্রাকচার** সহ সবকিছু অন্তর্ভুক্ত আছে। এটি সরাসরি আপনার `alap-framework/compiler/` ডিরেক্টরিতে বসিয়ে কাজ শুরু করা যাবে।

---

### 🏗️ নীলাং (Nilang) মাস্টার ব্লুপ্রিন্ট (৫-ফেজ রোডম্যাপ)

1. **ফেজ ১: কোর টুলচেইন (বর্তমান ফোকাস)** → Lexer, Parser, AST, এবং বেসিক REPL।
2. **ফেজ ২: টাইপ চেকার ও HIR** → স্ট্যাটিক টাইপ চেকিং (TypeScript/Go-স্টাইল) এবং High-Level IR অপ্টিমাইজেশন।
3. **ফেজ ৩: ব্যাকএন্ড জেনারেশন** → NABC Bytecode (VM-এর জন্য) অথবা সরাসরি C/Rust কোড জেনারেশন (Onuron OS-এর জন্য)।
4. **ফেজ ৪: স্ট্যান্ডার্ড লাইব্রেরি ও FFI** → `stdlib` (fs, net, json) এবং `libvlc` বা Onuron HAL-এর সাথে C-ABI ব্রিজ।
5. **ফেজ ৫: ডেভেলপার এক্সপেরিয়েন্স** → `nil` CLI, `nills` (LSP Server), VS Code এক্সটেনশন, এবং NilPM প্যাকেজ ম্যানেজার।

---

### 💻 ধাপ ১: কোর কম্পাইলার কোড (Go-তে)

এই কোডগুলো `alap-framework/compiler/` এর ভেতর সংশ্লিষ্ট ফোল্ডারে রাখুন। এটি Thorsten Ball-এর "Writing an Interpreter in Go" আর্কিটেকচারের ওপর ভিত্তি করে তৈরি, যা ইন্ডাস্ট্রিতে প্রমাণিত।

#### ১. `compiler/token/token.go` (টোকেন সংজ্ঞা)
```go
package token

type TokenType string

const (
	ILLEGAL = "ILLEGAL"
	EOF     = "EOF"

	// Identifiers + literals
	IDENT = "IDENT" // x, myComponent
	INT   = "INT"   // 12345

	// Operators
	ASSIGN   = "="
	PLUS     = "+"
	MINUS    = "-"
	BANG     = "!"
	ASTERISK = "*"
	SLASH    = "/"
	LT       = "<"
	GT       = ">"
	EQ       = "=="
	NOT_EQ   = "!="

	// Delimiters
	COMMA     = ","
	SEMICOLON = ";"
	LPAREN    = "("
	RPAREN    = ")"
	LBRACE    = "{"
	RBRACE    = "}"
	LBRACKET  = "["
	RBRACKET  = "]"
	DOT       = "."

	// Nilang Specific Keywords
	LET       = "LET"
	FN        = "FN"
	TRUE      = "TRUE"
	FALSE     = "FALSE"
	IF        = "IF"
	ELSE      = "ELSE"
	RETURN    = "RETURN"
	COMPONENT = "COMPONENT" // Alap UI Framework-এর জন্য
	IMPORT    = "IMPORT"    // মডিউল ইমপোর্টের জন্য
)

var keywords = map[string]TokenType{
	"let":       LET,
	"fn":        FN,
	"true":      TRUE,
	"false":     FALSE,
	"if":        IF,
	"else":      ELSE,
	"return":    RETURN,
	"component": COMPONENT,
	"import":    IMPORT,
}

func LookupIdent(ident string) TokenType {
	if tok, ok := keywords[ident]; ok {
		return tok
	}
	return IDENT
}

type Token struct {
	Type    TokenType
	Literal string
}
```

#### ২. `compiler/lexer/lexer.go` (সোর্স কোড পড়ার ইঞ্জিন)
```go
package lexer

import "github.com/joysriramsarkar/alap-framework/compiler/token"

type Lexer struct {
	input        string
	position     int
	readPosition int
	ch           byte
}

func New(input string) *Lexer {
	l := &Lexer{input: input}
	l.readChar()
	return l
}

func (l *Lexer) readChar() {
	if l.readPosition >= len(l.input) {
		l.ch = 0 // EOF
	} else {
		l.ch = l.input[l.readPosition]
	}
	l.position = l.readPosition
	l.readPosition += 1
}

func (l *Lexer) NextToken() token.Token {
	var tok token.Token
	l.skipWhitespace()

	switch l.ch {
	case '=':
		if l.peekChar() == '=' {
			ch := l.ch
			l.readChar()
			tok = token.Token{Type: token.EQ, Literal: string(ch) + string(l.ch)}
		} else {
			tok = newToken(token.ASSIGN, l.ch)
		}
	case '+', '-', '*', '/', '!', '<', '>', ';', ',', '(', ')', '{', '}', '[', ']', '.':
		tok = newToken(token.TokenType(l.ch), l.ch)
	case 0:
		tok.Literal = ""
		tok.Type = token.EOF
	default:
		if isLetter(l.ch) {
			tok.Literal = l.readIdentifier()
			tok.Type = token.LookupIdent(tok.Literal)
			return tok
		} else if isDigit(l.ch) {
			tok.Type = token.INT
			tok.Literal = l.readNumber()
			return tok
		} else {
			tok = newToken(token.ILLEGAL, l.ch)
		}
	}
	l.readChar()
	return tok
}

func (l *Lexer) skipWhitespace() {
	for l.ch == ' ' || l.ch == '\t' || l.ch == '\n' || l.ch == '\r' {
		l.readChar()
	}
}

func (l *Lexer) readIdentifier() string {
	position := l.position
	for isLetter(l.ch) {
		l.readChar()
	}
	return l.input[position:l.position]
}

func (l *Lexer) readNumber() string {
	position := l.position
	for isDigit(l.ch) {
		l.readChar()
	}
	return l.input[position:l.position]
}

func (l *Lexer) peekChar() byte {
	if l.readPosition >= len(l.input) {
		return 0
	}
	return l.input[l.readPosition]
}

func isLetter(ch byte) bool {
	return 'a' <= ch && ch <= 'z' || 'A' <= ch && ch <= 'Z' || ch == '_'
}

func isDigit(ch byte) bool {
	return '0' <= ch && ch <= '9'
}

func newToken(tokenType token.TokenType, ch byte) token.Token {
	return token.Token{Type: tokenType, Literal: string(ch)}
}
```

#### ৩. `compiler/ast/ast.go` (অ্যাবস্ট্রাক্ট সিনট্যাক্স ট্রি)
```go
package ast

import "github.com/joysriramsarkar/alap-framework/compiler/token"

type Node interface {
	TokenLiteral() string
	String() string
}

type Statement interface {
	Node
	statementNode()
}

type Expression interface {
	Node
	expressionNode()
}

type Program struct {
	Statements []Statement
}

func (p *Program) TokenLiteral() string {
	if len(p.Statements) > 0 {
		return p.Statements[0].TokenLiteral()
	}
	return ""
}

type LetStatement struct {
	Token token.Token
	Name  *Identifier
	Value Expression
}

func (ls *LetStatement) statementNode()       {}
func (ls *LetStatement) TokenLiteral() string { return ls.Token.Literal }

type Identifier struct {
	Token token.Token
	Value string
}

func (i *Identifier) expressionNode()      {}
func (i *Identifier) TokenLiteral() string { return i.Token.Literal }
func (i *Identifier) String() string       { return i.Value }
```

*(নোট: পূর্ণাঙ্গ Parser এবং Type Checker-এর জন্য আপনি এই AST-কে এক্সটেন্ড করবেন। এটি একটি সলিড ফাউন্ডেশন।)*

---

### 🎨 ধাপ ২: গিটহাব ও VS Code সিনট্যাক্স হাইলাইটিং

আপনার ভাষাকে গিটহাবে "Nilang" হিসেবে স্বীকৃতি দিতে এবং VS Code-এ রঙিন দেখাতে নিচের ফাইলগুলো আপনার `alap-framework` বা আলাদা `nilang` রিপোজিটরির রুটে যোগ করুন।

#### ১. `.github/languages.yml`
```yaml
Nilang:
  type: programming
  color: "#005A9C" # Onuron/Alap ইকোসিস্টেমের সাথে মানানসই গভীর নীল
  extensions:
    - ".nil"
  ace_mode: text
  codemirror_mode: nilang
  codemirror_mime_type: text/x-nilang
  aliases:
    - "nil"
    - "nilang"
```

#### ২. `.gitattributes`
```text
*.nil linguist-language=Nilang
*.nil linguist-detectable=true
*.nil linguist-documentation=false
```

#### ৩. `syntaxes/nilang.tmLanguage.json` (VS Code এবং GitHub-এর জন্য)
```json
{
  "name": "Nilang",
  "scopeName": "source.nil",
  "fileTypes": ["nil"],
  "patterns": [
    {
      "name": "keyword.control.nilang",
      "match": "\\b(let|fn|if|else|return|component|import|struct|type|match)\\b"
    },
    {
      "name": "storage.type.nilang",
      "match": "\\b(String|Int|Bool|Float|Any|Void|Component)\\b"
    },
    {
      "name": "constant.numeric.nilang",
      "match": "\\b\\d+(\\.\\d+)?\\b"
    },
    {
      "name": "string.quoted.double.nilang",
      "begin": "\"",
      "end": "\"",
      "patterns": [
        {
          "name": "constant.character.escape.nilang",
          "match": "\\\\."
        }
      ]
    },
    {
      "name": "comment.line.double-slash.nilang",
      "match": "//.*$"
    },
    {
      "name": "comment.block.nilang",
      "begin": "/\\*",
      "end": "\\*/"
    }
  ]
}
```
*(VS Code-এ এটি ব্যবহার করতে, একটি সাধারণ `package.json` সহ একটি ছোট VS Code এক্সটেনশন তৈরি করে এই `tmLanguage.json` ফাইলটি `contributes.grammars`-এ রেজিস্টার করুন।)*

---

### 📚 ধাপ ৩: ডকুমেন্টেশন কাঠামো (Docs)

একটি সিরিয়াস ল্যাঙ্গুয়েজের জন্য ডকুমেন্টেশন কোডের চেয়েও বেশি গুরুত্বপূর্ণ। আপনার রিপোতে `docs/` ফোল্ডারটি এই কাঠামোতে তৈরি করুন:

```text
docs/
├── README.md                 # Nilang-এর দর্শন, ফিচার, এবং কুইক স্টার্ট
├── getting-started/
│   ├── installation.md       # Go/Rust টুলচেইন সেটআপ গাইড
│   └── your-first-nil.md     # "Hello, Onuron!" অ্যাপ তৈরি
├── language-tour/
│   ├── variables-and-types.md
│   ├── functions-and-closures.md
│   ├── components-and-ui.md  # Alap Framework-এর সাথে ইন্টিগ্রেশন
│   └── concurrency.md        # Go-স্টাইল Goroutine/Actor মডেল
├── compiler-internals/       # যারা কম্পাইলারে কন্ট্রিবিউট করতে চায় তাদের জন্য
│   ├── lexer.md
│   ├── parser.md
│   └── codegen.md
└── rfcs/                     # ভবিষ্যতের ফিচারের জন্য Request for Comments
    └── 001-ffi-with-c.md
```

**নমুনা `docs/README.md` কনটেন্ট:**
```markdown
# 🌟 Nilang (নীলাং) Programming Language

Nilang is a modern, statically-typed, and concurrent programming language designed for the **Alap Framework** and **Onuron OS**. It combines the declarative UI power of ArkTS, the safety of Rust, and the simplicity of Go.

## ✨ Features
- 🧩 **Native Component Model**: `component` keyword for declarative UI.
- ⚡ **Blazing Fast Compilation**: Powered by a Go-based toolchain (`nilc`).
- 🔒 **Memory Safe**: Designed with Onuron OS's 100% Rust userspace in mind (via FFI).
- 🌐 **Cross-Platform**: Write once, compile to `.nilax` (Onuron), `.apk` (Android), or Linux binaries.

## 🚀 Quick Start
```nil
import "ui"

component App {
    let count = 0

    fn render() {
        ui.Text("Hello, Onuron OS! Count: \(count)")
    }
}
```
```

---

### 🛠️ ধাপ ৪: এটি কীভাবে আপনার ইকোসিস্টেমের সাথে ফিট করবে?

1. **Alap Framework-এর সাথে**: আপনি যখন `nil build onuron` কমান্ড চালাবেন, `nilc` (Nilang Compiler) প্রথমে `.nil` ফাইলগুলোকে পড়বে, Lexer/Parser দিয়ে AST তৈরি করবে, এবং সেটিকে NABC Bytecode অথবা সরাসরি C/Rust FFI কোডে রূপান্তর করবে। এরপর Alap-এর `platform/onuron/` অ্যাডাপ্টার সেটিকে `.nilax` বান্ডিলে প্যাক করবে।
2. **Onuron OS-এর সাথে**: Onuron OS-এর `nilui` (Declarative reactive UI framework) সরাসরি এই Nilang-এর `component` কিওয়ার্ড থেকে জেনারেট হওয়া AST-কে কনজিউম করবে। 
3. **VLC/ডিগোডিং-এর সাথে**: Nilang-এ আপনি শুধু `extern fn decode_video(ptr: *C.void)` ডিক্লেয়ার করবেন। কম্পাইলার এটিকে C-ABI তে ম্যাপ করবে, এবং রানটাইমে `libvlc.so` কল করবে।

---

### ▶️ পরবর্তী পদক্ষেপ (আপনার জন্য অ্যাকশন প্ল্যান)

1. **আজই**: `alap-framework` রিপোতে `compiler/token`, `compiler/lexer`, এবং `compiler/ast` ফোল্ডার তৈরি করে উপরের কোডগুলো পেস্ট করুন।
2. **আগামীকাল**: একটি সাধারণ `compiler/parser/parser.go` লিখুন যা `let x = 5;` কে AST-তে রূপান্তর করতে পারে। (আপনি চাইলে আমি এর কোডও জেনারেট করে দিতে পারি)।
3. **এই সপ্তাহে**: `.github/languages.yml` এবং `tmLanguage.json` যোগ করে একটি ডামি `.nil` ফাইল পুশ করুন এবং গিটহাবে ভাষার স্বীকৃতি চেক করুন।

জয়শ্রীরাম, আপনি যে পথে হাঁটছেন তা "টয় প্রজেক্ট" নয়, এটি একটি **সিস্টেমস-লেভেল আর্কিটেকচার**। এআই আপনাকে কোড লিখে দিতে পারে, কিন্তু এই কাঠামোটি (Architecture) এবং ভিশনটি শুধুই আপনার। 

আপনি কি চান আমি পরবর্তী ধাপ হিসেবে **Recursive Descent Parser (`parser.go`)** এবং একটি **বেসিক REPL (`cmd/nil/repl.go`)**-এর সম্পূর্ণ কোড জেনারেট করে দিই, যাতে আপনি টার্মিনালে `nil` টাইপ করেই আপনার ভাষা টেস্ট করতে পারেন?

চ্যালেঞ্জ গ্রহণ করলাম, জয়শ্রীরাম। 

একটি প্রোগ্রামিং ল্যাঙ্গুয়েজের "প্রাণ" হলো তার **Parser** (যো কোড পড়ে অর্থ বোঝে) এবং **Evaluator/REPL** (যো কোড রান করে রেজাল্ট দেখায়)। 

নিচে আমি **Nilang**-এর একটি সম্পূর্ণ কার্যকরী **Minimum Viable Compiler (MVC)** এর কোড দিচ্ছি। এটি `let` ভেরিয়েবল, Integer, Boolean, এবং `+`, `-`, `*`, `/`, `==`, `!=` অপারেটর সাপোর্ট করবে। আপনি এটি কপি করে সরাসরি আপনার `alap-framework` এ বসিয়ে রান করতে পারবেন।

---

### 📂 ফাইল স্ট্রাকচার আপডেট
আপনার `alap-framework/compiler/` ডিরেক্টরিতে এই ফাইলগুলো তৈরি করুন:

---

### ১. AST এক্সটেনশন (`compiler/ast/ast.go`)
আগের AST-এর সাথে এক্সপ্রেশন হ্যান্ডলিং যোগ করছি।

```go
package ast

import (
	"bytes"
	"strings"
	"github.com/joysriramsarkar/alap-framework/compiler/token"
)

// Expression Statement
type ExpressionStatement struct {
	Token      token.Token // the first token of the expression
	Expression Expression
}
func (es *ExpressionStatement) statementNode() {}
func (es *ExpressionStatement) TokenLiteral() string { return es.Token.Literal }
func (es *ExpressionStatement) String() string {
	if es.Expression != nil {
		return es.Expression.String()
	}
	return ""
}

// Integer Literal
type IntegerLiteral struct {
	Token token.Token
	Value int64
}
func (il *IntegerLiteral) expressionNode() {}
func (il *IntegerLiteral) TokenLiteral() string { return il.Token.Literal }
func (il *IntegerLiteral) String() string { return il.Token.Literal }

// Prefix Expression (e.g., -5, !true)
type PrefixExpression struct {
	Token    token.Token // The prefix token, e.g., '!'
	Operator string
	Right    Expression
}
func (pe *PrefixExpression) expressionNode() {}
func (pe *PrefixExpression) TokenLiteral() string { return pe.Token.Literal }
func (pe *PrefixExpression) String() string {
	var out bytes.Buffer
	out.WriteString("(")
	out.WriteString(pe.Operator)
	out.WriteString(pe.Right.String())
	out.WriteString(")")
	return out.String()
}

// Infix Expression (e.g., 5 + 5, 10 == 10)
type InfixExpression struct {
	Token    token.Token // The operator token, e.g., '+'
	Left     Expression
	Operator string
	Right    Expression
}
func (ie *InfixExpression) expressionNode() {}
func (ie *InfixExpression) TokenLiteral() string { return ie.Token.Literal }
func (ie *InfixExpression) String() string {
	var out bytes.Buffer
	out.WriteString("(")
	out.WriteString(ie.Left.String())
	out.WriteString(" " + ie.Operator + " ")
	out.WriteString(ie.Right.String())
	out.WriteString(")")
	return out.String()
}

// Update LetStatement String() method
func (ls *LetStatement) String() string {
	var out bytes.Buffer
	out.WriteString(ls.TokenLiteral() + " ")
	out.WriteString(ls.Name.String())
	out.WriteString(" = ")
	if ls.Value != nil {
		out.WriteString(ls.Value.String())
	}
	out.WriteString(";")
	return out.String()
}
