## 📦 ধাপ ২: বাইটকোড কম্পাইলার (`compiler/compiler/compiler.go`)

এটি AST-কে বাইটকোডে রূপান্তরিত করে।

```go
package compiler

import (
	"fmt"
	"github.com/joysriramsarkar/alap-framework/compiler/ast"
	"github.com/joysriramsarkar/alap-framework/compiler/object"
	"github.com/joysriramsarkar/alap-framework/compiler/vm"
)

type EmittedInstruction struct {
	Opcode   vm.OpCode
	Position int
}

type Bytecode struct {
	Instructions vm.Code
	Constants    []object.Object
}

type Compiler struct {
	constants []object.Object
	symbolTable *SymbolTable

	scopes []CompilationScope
	scopeIndex int
}

type CompilationScope struct {
	instructions vm.Code
	lastEmittedInstruction EmittedInstruction
	previousEmittedInstruction EmittedInstruction
}

func NewCompiler() *Compiler {
	mainScope := CompilationScope{
		instructions: vm.Code{},
	}

	return &Compiler{
		constants:   []object.Object{},
		symbolTable: NewSymbolTable(),
		scopes:      []CompilationScope{mainScope},
		scopeIndex:  0,
	}
}

func (c *Compiler) Compile(node ast.Node) error {
	switch node := node.(type) {
	case *ast.Program:
		for _, s := range node.Statements {
			err := c.Compile(s)
			if err != nil {
				return err
			}
		}

	case *ast.ExpressionStatement:
		err := c.Compile(node.Expression)
		if err != nil {
			return err
		}
		c.emit(vm.OpPop)

	case *ast.IntegerLiteral:
		integer := &object.Integer{Value: node.Value}
		c.emit(vm.OpConstant, c.addConstant(integer))

	case *ast.Boolean:
		if node.Value {
			c.emit(vm.OpTrue)
		} else {
			c.emit(vm.OpFalse)
		}

	case *ast.PrefixExpression:
		err := c.Compile(node.Right)
		if err != nil {
			return err
		}

		switch node.Operator {
		case "!":
			c.emit(vm.OpNot)
		case "-":
			c.emit(vm.OpMinus)
		default:
			return fmt.Errorf("unknown operator %s", node.Operator)
		}

	case *ast.InfixExpression:
		// Compile right first for correct stack order
		err := c.Compile(node.Right)
		if err != nil {
			return err
		}
		err = c.Compile(node.Left)
		if err != nil {
			return err
		}

		switch node.Operator {
		case "+":
			c.emit(vm.OpAdd)
		case "-":
			c.emit(vm.OpSub)
		case "*":
			c.emit(vm.OpMul)
		case "/":
			c.emit(vm.OpDiv)
		case "==":
			c.emit(vm.OpEqual)
		case "!=":
			c.emit(vm.OpNotEqual)
		case "<":
			c.emit(vm.OpLessThan)
		case ">":
			c.emit(vm.OpGreaterThan)
		default:
			return fmt.Errorf("unknown operator %s", node.Operator)
		}

	case *ast.IfExpression:
		err := c.Compile(node.Condition)
		if err != nil {
			return err
		}

		// Emit jump-not-truthy placeholder
		jumpNotTruthyPos := c.emit(vm.OpJumpNotTruthy, 9999)

		err = c.Compile(node.Consequence)
		if err != nil {
			return err
		}

		// If consequence ends with a statement, we need to handle the last expression
		// For now, add a pop if the last instruction was not a jump/return
		if c.lastInstructionIsPop() {
			c.removeLastPop()
		}

		// Jump over else block
		jumpPos := c.emit(vm.OpJump, 9999)

		// Patch the jump-not-truthy to point here
		c.changeOperand(jumpNotTruthyPos, c.currentInstructionPosition())

		if node.Alternative == nil {
			c.emit(vm.OpNull)
		} else {
			err := c.Compile(node.Alternative)
			if err != nil {
				return err
			}
			if c.lastInstructionIsPop() {
				c.removeLastPop()
			}
		}

		// Patch the jump to point here
		c.changeOperand(jumpPos, c.currentInstructionPosition())

	case *ast.LetStatement:
		err := c.Compile(node.Value)
		if err != nil {
			return err
		}

		symbol := c.symbolTable.Define(node.Name.Value)
		if symbol.Scope == GlobalScope {
			c.emit(vm.OpSetGlobal, symbol.Index)
		} else {
			c.emit(vm.OpSetLocal, symbol.Index)
		}

	case *ast.Identifier:
		symbol, ok := c.symbolTable.Resolve(node.Value)
		if !ok {
			return fmt.Errorf("undefined variable %s", node.Value)
		}

		if symbol.Scope == GlobalScope {
			c.emit(vm.OpGetGlobal, symbol.Index)
		} else {
			c.emit(vm.OpGetLocal, symbol.Index)
		}

	case *ast.StringLiteral:
		str := &object.String{Value: node.Value}
		c.emit(vm.OpConstant, c.addConstant(str))

	case *ast.ArrayLiteral:
		for _, el := range node.Elements {
			err := c.Compile(el)
			if err != nil {
				return err
			}
		}
		c.emit(vm.OpArray, len(node.Elements))

	case *ast.IndexExpression:
		err := c.Compile(node.Index)
		if err != nil {
			return err
		}
		err = c.Compile(node.Left)
		if err != nil {
			return err
		}
		c.emit(vm.OpIndex)

	case *ast.BlockStatement:
		for _, s := range node.Statements {
			err := c.Compile(s)
			if err != nil {
				return err
			}
		}

	case *ast.FunctionLiteral:
		err := c.enterScope()
		if err != nil {
			return err
		}

		for _, p := range node.Parameters {
			c.symbolTable.Define(p.Value)
		}

		err = c.Compile(node.Body)
		if err != nil {
			return err
		}

		// If the function body doesn't end with a return, add one
		if !c.lastInstructionIsReturn() {
			c.emit(vm.OpReturn)
		}

		numLocals := c.symbolTable.NumDefinitions()
		instructions := c.exitScope()

		compiledFn := &object.CompiledFunction{
			Instructions: instructions,
			NumLocals:    numLocals,
			NumParams:    len(node.Parameters),
		}
		c.emit(vm.OpConstant, c.addConstant(compiledFn))

	case *ast.CallExpression:
		err := c.Compile(node.Function)
		if err != nil {
			return err
		}

		for _, arg := range node.Arguments {
			err := c.Compile(arg)
			if err != nil {
				return err
			}
		}
		c.emit(vm.OpCall, len(node.Arguments))

	case *ast.ReturnStatement:
		if node.ReturnValue == nil {
			c.emit(vm.OpReturn)
		} else {
			err := c.Compile(node.ReturnValue)
			if err != nil {
				return err
			}
			c.emit(vm.OpReturnValue)
		}

	case nil:
		// Do nothing

	default:
		return fmt.Errorf("unknown node type: %T", node)
	}

	return nil
}

// --- Helper Methods ---

func (c *Compiler) Bytecode() *Bytecode {
	return &Bytecode{
		Instructions: c.currentInstructions(),
		Constants:    c.constants,
	}
}

func (c *Compiler) addConstant(obj object.Object) int {
	c.constants = append(c.constants, obj)
	return len(c.constants) - 1
}

func (c *Compiler) emit(op vm.OpCode, operands ...int) int {
	ins := vm.Make(op, operands...)
	pos := c.addInstruction(ins)
	c.setLastInstruction(op, pos)
	return pos
}

func (c *Compiler) addInstruction(ins []byte) int {
	posNewInstruction := len(c.currentInstructions())
	c.scopes[c.scopeIndex].instructions = append(c.currentInstructions(), ins...)
	return posNewInstruction
}

func (c *Compiler) currentInstructions() vm.Code {
	return c.scopes[c.scopeIndex].instructions
}

func (c *Compiler) setLastInstruction(op vm.OpCode, pos int) {
	previous := c.scopes[c.scopeIndex].lastEmittedInstruction
	c.scopes[c.scopeIndex].previousEmittedInstruction = previous
	c.scopes[c.scopeIndex].lastEmittedInstruction = EmittedInstruction{Opcode: op, Position: pos}
}

func (c *Compiler) lastInstructionIsPop() bool {
	return c.scopes[c.scopeIndex].lastEmittedInstruction.Opcode == vm.OpPop
}

func (c *Compiler) lastInstructionIsReturn() bool {
	last := c.scopes[c.scopeIndex].lastEmittedInstruction.Opcode
	prev := c.scopes[c.scopeIndex].previousEmittedInstruction.Opcode
	return last == vm.OpReturnValue || last == vm.OpReturn || 
	       (last == vm.OpNull && prev == vm.OpReturn)
}

func (c *Compiler) removeLastPop() {
	last := c.scopes[c.scopeIndex].lastEmittedInstruction
	prev := c.scopes[c.scopeIndex].previousEmittedInstruction
	c.scopes[c.scopeIndex].instructions = c.currentInstructions()[:last.Position]
	c.scopes[c.scopeIndex].lastEmittedInstruction = prev
}

func (c *Compiler) changeOperand(opPos int, operand int) {
	op := vm.OpCode(c.currentInstructions()[opPos])
	newInstruction := vm.Make(op, operand)
	c.replaceInstruction(opPos, newInstruction)
}

func (c *Compiler) replaceInstruction(pos int, newInstruction []byte) {
	ins := c.currentInstructions()
	for i := 0; i < len(newInstruction); i++ {
		ins[pos+i] = newInstruction[i]
	}
}

func (c *Compiler) currentInstructionPosition() int {
	return len(c.currentInstructions())
}

func (c *Compiler) enterScope() error {
	scope := CompilationScope{
		instructions: vm.Code{},
	}
	c.scopes = append(c.scopes, scope)
	c.scopeIndex++
	c.symbolTable = NewEnclosedSymbolTable(c.symbolTable)
	return nil
}

func (c *Compiler) exitScope() vm.Code {
	instructions := c.currentInstructions()
	c.scopes = c.scopes[:len(c.scopes)-1]
	c.scopeIndex--
	c.symbolTable = c.symbolTable.Outer
	return instructions
}
```

