## 📦 ধাপ ৪: ভিএম আপডেট (`compiler/vm/vm.go`)

নতুন অপকোড এবং ফাংশন কল সাপোর্ট যোগ করুন।

```go
package vm

// OpCode আপডেট করুন:
const (
	OpConstant OpCode = iota
	OpPop
	OpAdd
	OpSub
	OpMul
	OpDiv
	OpTrue
	OpFalse
	OpEqual
	OpNotEqual
	OpLessThan
	OpGreaterThan
	OpJump
	OpJumpNotTruthy
	OpNull
	OpGetGlobal
	OpSetGlobal
	OpGetLocal
	OpSetLocal
	OpArray
	OpIndex
	OpNot
	OpMinus
	OpCall
	OpReturnValue
	OpReturn
	OpHalt
)

// Make ফাংশন আপডেট করুন:
func Make(op OpCode, operands ...int) []byte {
	instruction := make([]byte, 0)
	instruction = append(instruction, byte(op))

	switch op {
	case OpConstant, OpJump, OpJumpNotTruthy:
		instruction = append(instruction, uint16ToBytes(uint16(operands[0]))...)
	case OpGetGlobal, OpSetGlobal, OpGetLocal, OpSetLocal, OpArray, OpCall:
		instruction = append(instruction, byte(operands[0]))
	}

	return instruction
}

// Disassemble আপডেট করুন:
func Disassemble(code Code) string {
	var buf bytes.Buffer
	offset := 0
	for offset < len(code) {
		op := OpCode(code[offset])
		var inst Instruction

		switch op {
		case OpConstant, OpJump, OpJumpNotTruthy:
			inst = code[offset : offset+3]
			offset += 3
		case OpGetGlobal, OpSetGlobal, OpGetLocal, OpSetLocal, OpArray, OpCall:
			inst = code[offset : offset+2]
			offset += 2
		default:
			inst = code[offset : offset+1]
			offset += 1
		}

		fmt.Fprintf(&buf, "%04d %s\n", offset-len(inst), inst.String())
	}
	return buf.String()
}

// VM struct আপডেট করুন:
const MaxFrames = 1024

type Frame struct {
	instructions vm.Code
	ip           int
	basePointer  int
}

func NewFrame(instructions vm.Code, basePointer int) *Frame {
	return &Frame{
		instructions: instructions,
		ip:           -1,
		basePointer:  basePointer,
	}
}

type VM struct {
	constants []object.Object
	stack     []object.Object
	sp        int
	globals   []object.Object
	frames    []*Frame
	frameIndex int
}

func NewVM(bytecode *Bytecode) *VM {
	mainFrame := NewFrame(bytecode.Instructions, 0)
	frames := make([]*Frame, MaxFrames)
	frames[0] = mainFrame

	return &VM{
		constants:  bytecode.Constants,
		stack:      make([]object.Object, StackSize),
		sp:         0,
		globals:    make([]object.Object, GlobalsSize),
		frames:     frames,
		frameIndex: 1,
	}
}

func (vm *VM) currentFrame() *Frame {
	return vm.frames[vm.frameIndex-1]
}

func (vm *VM) pushFrame(f *Frame) {
	vm.frames[vm.frameIndex] = f
	vm.frameIndex++
}

func (vm *VM) popFrame() *Frame {
	vm.frameIndex--
	return vm.frames[vm.frameIndex]
}

// Run ফাংশন সম্পূর্ণ রিপ্লেস করুন:
func (vm *VM) Run() error {
	for vm.currentFrame().ip < len(vm.currentFrame().instructions)-1 {
		vm.currentFrame().ip++

		ip := vm.currentFrame().ip
		ins := vm.currentFrame().instructions
		op := OpCode(ins[ip])

		switch op {
		case OpConstant:
			constIndex := ReadUint16(ins[ip+1 : ip+3])
			vm.currentFrame().ip += 2
			err := vm.push(vm.constants[constIndex])
			if err != nil {
				return err
			}

		case OpPop:
			vm.pop()

		case OpAdd, OpSub, OpMul, OpDiv:
			err := vm.executeBinaryOperation(op)
			if err != nil {
				return err
			}

		case OpTrue:
			err := vm.push(&object.Boolean{Value: true})
			if err != nil {
				return err
			}

		case OpFalse:
			err := vm.push(&object.Boolean{Value: false})
			if err != nil {
				return err
			}

		case OpEqual, OpNotEqual, OpLessThan, OpGreaterThan:
			err := vm.executeComparison(op)
			if err != nil {
				return err
			}

		case OpJump:
			pos := int(ReadUint16(ins[ip+1 : ip+3]))
			vm.currentFrame().ip = pos - 1

		case OpJumpNotTruthy:
			pos := int(ReadUint16(ins[ip+1 : ip+3]))
			vm.currentFrame().ip += 2

			condition := vm.pop()
			if !isTruthy(condition) {
				vm.currentFrame().ip = pos - 1
			}

		case OpNull:
			err := vm.push(&object.Null{})
			if err != nil {
				return err
			}

		case OpSetGlobal:
			globalIndex := int(ins[ip+1])
			vm.currentFrame().ip++
			vm.globals[globalIndex] = vm.pop()

		case OpGetGlobal:
			globalIndex := int(ins[ip+1])
			vm.currentFrame().ip++
			err := vm.push(vm.globals[globalIndex])
			if err != nil {
				return err
			}

		case OpSetLocal:
			localIndex := int(ins[ip+1])
			vm.currentFrame().ip++
			frame := vm.currentFrame()
			vm.stack[frame.basePointer+localIndex] = vm.pop()

		case OpGetLocal:
			localIndex := int(ins[ip+1])
			vm.currentFrame().ip++
			frame := vm.currentFrame()
			err := vm.push(vm.stack[frame.basePointer+localIndex])
			if err != nil {
				return err
			}

		case OpArray:
			numElements := int(ins[ip+1])
			vm.currentFrame().ip++
			elements := vm.popN(numElements)
			err := vm.push(&object.Array{Elements: elements})
			if err != nil {
				return err
			}

		case OpIndex:
			index := vm.pop()
			left := vm.pop()
			err := vm.executeIndexExpression(left, index)
			if err != nil {
				return err
			}

		case OpNot:
			err := vm.executeNotOperator()
			if err != nil {
				return err
			}

		case OpMinus:
			err := vm.executeMinusOperator()
			if err != nil {
				return err
			}

		case OpCall:
			numArgs := int(ins[ip+1])
			vm.currentFrame().ip++
			err := vm.executeCall(numArgs)
			if err != nil {
				return err
			}

		case OpReturnValue:
			returnValue := vm.pop()
			frame := vm.popFrame()
			vm.sp = frame.basePointer - 1
			err := vm.push(returnValue)
			if err != nil {
				return err
			}

		case OpReturn:
			frame := vm.popFrame()
			vm.sp = frame.basePointer - 1
			err := vm.push(&object.Null{})
			if err != nil {
				return err
			}

		case OpHalt:
			return nil
		}
	}

	return nil
}

// নতুন হেল্পার ফাংশন:
func (vm *VM) popN(n int) []object.Object {
	elements := make([]object.Object, n)
	for i := n - 1; i >= 0; i-- {
		elements[i] = vm.pop()
	}
	return elements
}

func (vm *VM) executeCall(numArgs int) error {
	callee := vm.stack[vm.sp-1-numArgs]

	switch callee := callee.(type) {
	case *object.CompiledFunction:
		return vm.callFunction(callee, numArgs)
	case *object.Builtin:
		return vm.callBuiltin(callee, numArgs)
	default:
		return fmt.Errorf("calling non-function")
	}
}

func (vm *VM) callFunction(fn *object.CompiledFunction, numArgs int) error {
	if numArgs != fn.NumParams {
		return fmt.Errorf("wrong number of arguments: want=%d, got=%d", fn.NumParams, numArgs)
	}

	frame := NewFrame(fn.Instructions, vm.sp-numArgs)
	vm.pushFrame(frame)
	vm.sp = frame.basePointer + fn.NumLocals

	return nil
}

func (vm *VM) callBuiltin(fn *object.Builtin, numArgs int) error {
	args := vm.popN(numArgs)
	// Pop the builtin function itself
	vm.pop()

	result := fn.Fn(args...)
	return vm.push(result)
}

func (vm *VM) executeIndexExpression(left, index object.Object) error {
	switch {
	case left.Type() == object.ARRAY_OBJ && index.Type() == object.INTEGER_OBJ:
		return vm.executeArrayIndex(left, index)
	case left.Type() == object.STRING_OBJ && index.Type() == object.INTEGER_OBJ:
		return vm.executeStringIndex(left, index)
	default:
		return fmt.Errorf("index operator not supported: %s", left.Type())
	}
}

func (vm *VM) executeArrayIndex(array, index object.Object) error {
	arrayObj := array.(*object.Array)
	idx := index.(*object.Integer).Value
	max := int64(len(arrayObj.Elements) - 1)

	if idx < 0 || idx > max {
		return vm.push(&object.Null{})
	}
	return vm.push(arrayObj.Elements[idx])
}

func (vm *VM) executeStringIndex(str, index object.Object) error {
	strObj := str.(*object.String)
	idx := index.(*object.Integer).Value
	max := int64(len(strObj.Value) - 1)

	if idx < 0 || idx > max {
		return vm.push(&object.Null{})
	}
	return vm.push(&object.String{Value: string(strObj.Value[idx])})
}

func (vm *VM) executeNotOperator() error {
	operand := vm.pop()
	switch {
	case operand == TRUE:
		return vm.push(FALSE)
	case operand == FALSE:
		return vm.push(TRUE)
	case operand == NULL:
		return vm.push(TRUE)
	default:
		return vm.push(FALSE)
	}
}

func (vm *VM) executeMinusOperator() error {
	operand := vm.pop()
	if operand.Type() != object.INTEGER_OBJ {
		return fmt.Errorf("unsupported type for negation: %s", operand.Type())
	}
	value := operand.(*object.Integer).Value
	return vm.push(&object.Integer{Value: -value})
}

func (vm *VM) executeComparison(op OpCode) error {
	right := vm.pop()
	left := vm.pop()

	leftType := left.Type()
	rightType := right.Type()

	switch {
	case leftType == object.INTEGER_OBJ && rightType == object.INTEGER_OBJ:
		return vm.executeIntegerComparison(op, left, right)
	case leftType == object.STRING_OBJ && rightType == object.STRING_OBJ:
		return vm.executeStringComparison(op, left, right)
	case leftType == object.BOOLEAN_OBJ && rightType == object.BOOLEAN_OBJ:
		return vm.executeBooleanComparison(op, left, right)
	default:
		return fmt.Errorf("unsupported types for comparison: %s %s", leftType, rightType)
	}
}

func (vm *VM) executeIntegerComparison(op OpCode, left, right object.Object) error {
	leftVal := left.(*object.Integer).Value
	rightVal := right.(*object.Integer).Value

	switch op {
	case OpEqual:
		return vm.push(nativeBoolToBooleanObject(leftVal == rightVal))
	case OpNotEqual:
		return vm.push(nativeBoolToBooleanObject(leftVal != rightVal))
	case OpLessThan:
		return vm.push(nativeBoolToBooleanObject(leftVal < rightVal))
	case OpGreaterThan:
		return vm.push(nativeBoolToBooleanObject(leftVal > rightVal))
	default:
		return fmt.Errorf("unknown operator: %d", op)
	}
}

func (vm *VM) executeStringComparison(op OpCode, left, right object.Object) error {
	leftVal := left.(*object.String).Value
	rightVal := right.(*object.String).Value

	switch op {
	case OpEqual:
		return vm.push(nativeBoolToBooleanObject(leftVal == rightVal))
	case OpNotEqual:
		return vm.push(nativeBoolToBooleanObject(leftVal != rightVal))
	case OpLessThan:
		return vm.push(nativeBoolToBooleanObject(leftVal < rightVal))
	case OpGreaterThan:
		return vm.push(nativeBoolToBooleanObject(leftVal > rightVal))
	default:
		return fmt.Errorf("unknown operator: %d", op)
	}
}

func (vm *VM) executeBooleanComparison(op OpCode, left, right object.Object) error {
	leftVal := left.(*object.Boolean).Value
	rightVal := right.(*object.Boolean).Value

	switch op {
	case OpEqual:
		return vm.push(nativeBoolToBooleanObject(leftVal == rightVal))
	case OpNotEqual:
		return vm.push(nativeBoolToBooleanObject(leftVal != rightVal))
	default:
		return fmt.Errorf("unknown operator: %d", op)
	}
}
