## 🔄 অংশ ১: While Loop সাপোর্ট

### `compiler/token/token.go` — আপডেট করুন

```go
package token

type TokenType string

const (
	ILLEGAL = "ILLEGAL"
	EOF     = "EOF"

	// Identifiers + literals
	IDENT  = "IDENT"
	INT    = "INT"
	STRING = "STRING"

	// Operators
	ASSIGN   = "="
	PLUS     = "+"
	MINUS    = "-"
	BANG     = "!"
	ASTERISK = "*"
	SLASH    = "/"
	LT       = "<"
	GT       = ">"
	EQ       = "=="
	NOT_EQ   = "!="

	// Delimiters
	COMMA     = ","
	SEMICOLON = ";"
	COLON     = ":"
	LPAREN    = "("
	RPAREN    = ")"
	LBRACE    = "{"
	RBRACE    = "}"
	LBRACKET  = "["
	RBRACKET  = "]"
	DOT       = "."

	// Nilang Keywords
	LET       = "LET"
	FN        = "FN"
	TRUE      = "TRUE"
	FALSE     = "FALSE"
	IF        = "IF"
	ELSE      = "ELSE"
	RETURN    = "RETURN"
	COMPONENT = "COMPONENT"
	IMPORT    = "IMPORT"
	WHILE     = "WHILE"     // ← নতুন
)

var keywords = map[string]TokenType{
	"let":       LET,
	"fn":        FN,
	"true":      TRUE,
	"false":     FALSE,
	"if":        IF,
	"else":      ELSE,
	"return":    RETURN,
	"component": COMPONENT,
	"import":    IMPORT,
	"while":     WHILE, // ← নতুন
}

func LookupIdent(ident string) TokenType {
	if tok, ok := keywords[ident]; ok {
		return tok
	}
	return IDENT
}

type Token struct {
	Type    TokenType
	Literal string
}
```

### `compiler/ast/ast.go` — যোগ করুন

```go
// WhileStatement: while (condition) { body }
type WhileStatement struct {
	Token     token.Token // the 'while' token
	Condition Expression
	Body      *BlockStatement
}

func (ws *WhileStatement) statementNode()       {}
func (ws *WhileStatement) TokenLiteral() string { return ws.Token.Literal }
func (ws *WhileStatement) String() string {
	var out bytes.Buffer
	out.WriteString("while")
	out.WriteString(ws.Condition.String())
	out.WriteString(" ")
	out.WriteString(ws.Body.String())
	return out.String()
}
```

### `compiler/parser/parser.go` — যোগ করুন

```go
// parseStatement() ফাংশনের switch-এ যোগ করুন:
case token.WHILE:
	return p.parseWhileStatement()

// এই ফাংশনটি যোগ করুন:
func (p *Parser) parseWhileStatement() *ast.WhileStatement {
	stmt := &ast.WhileStatement{Token: p.curToken}

	if !p.expectPeek(token.LPAREN) {
		return nil
	}

	p.nextToken()
	stmt.Condition = p.parseExpression(LOWEST)

	if !p.expectPeek(token.RPAREN) {
		return nil
	}

	if !p.expectPeek(token.LBRACE) {
		return nil
	}

	stmt.Body = p.parseBlockStatement()

	return stmt
}
```

### `compiler/compiler/compiler.go` — যোগ করুন

```go
// Compile() ফাংশনের switch-এ যোগ করুন:
case *ast.WhileStatement:
	// Condition start position
	conditionStart := c.currentInstructionPosition()

	// Compile condition
	err := c.Compile(node.Condition)
	if err != nil {
		return err
	}

	// Jump to end if condition is false
	jumpNotTruthyPos := c.emit(vm.OpJumpNotTruthy, 9999)

	// Compile body
	err = c.Compile(node.Body)
	if err != nil {
		return err
	}

	// If body ends with a pop (expression statement), remove it
	if c.lastInstructionIsPop() {
		c.removeLastPop()
	}

	// Jump back to condition
	c.emit(vm.OpJump, conditionStart)

	// Patch the jump-not-truthy to point here (after the loop)
	afterLoopPos := c.currentInstructionPosition()
	c.changeOperand(jumpNotTruthyPos, afterLoopPos)

	// While loop returns null
	c.emit(vm.OpNull)
```

