## ✨ অংশ ২: String Interpolation সাপোর্ট

### `compiler/ast/ast.go` — যোগ করুন

```go
// StringTemplate: "Hello, \(name)!"
type StringTemplate struct {
	Token token.Token // the opening '"' token
	Parts []TemplatePart
}

type TemplatePart struct {
	IsExpression bool
	Literal      string     // string segment
	Expression   Expression // interpolated expression
}

func (st *StringTemplate) expressionNode()      {}
func (st *StringTemplate) TokenLiteral() string { return st.Token.Literal }
func (st *StringTemplate) String() string {
	var out bytes.Buffer
	out.WriteString("\"")
	for _, part := range st.Parts {
		if part.IsExpression {
			out.WriteString("\\(")
			out.WriteString(part.Expression.String())
			out.WriteString(")")
		} else {
			out.WriteString(part.Literal)
		}
	}
	out.WriteString("\"")
	return out.String()
}
```

### `compiler/lexer/lexer.go` — আপডেট করুন

```go
// readString() ফাংশনটি এই ভার্সন দিয়ে রিপ্লেস করুন:
func (l *Lexer) readString() string {
	position := l.position + 1
	var sb strings.Builder

	for {
		l.readChar()

		if l.ch == 0 {
			break // EOF
		}

		if l.ch == '"' {
			break // End of string
		}

		if l.ch == '\\' {
			l.readChar()
			switch l.ch {
			case 'n':
				sb.WriteByte('\n')
			case 't':
				sb.WriteByte('\t')
			case 'r':
				sb.WriteByte('\r')
			case '\\':
				sb.WriteByte('\\')
			case '"':
				sb.WriteByte('"')
			case '(':
				// String interpolation marker: \(
				sb.WriteString("\\(")
			default:
				sb.WriteByte('\\')
				sb.WriteByte(l.ch)
			}
			continue
		}

		sb.WriteByte(l.ch)
	}

	return sb.String()
}
```

### `compiler/parser/parser.go` — যোগ করুন

```go
// parseStringLiteral() ফাংশনটি এই ভার্সন দিয়ে রিপ্লেস করুন:
func (p *Parser) parseStringLiteral() ast.Expression {
	rawValue := p.curToken.Literal

	// Check if it contains interpolation
	if !strings.Contains(rawValue, "\\(") {
		return &ast.StringLiteral{Token: p.curToken, Value: rawValue}
	}

	// Parse as template
	return p.parseStringTemplate(rawValue)
}

func (p *Parser) parseStringTemplate(raw string) ast.Expression {
	template := &ast.StringTemplate{Token: p.curToken}
	template.Parts = []ast.TemplatePart{}

	i := 0
	for i < len(raw) {
		// Find next interpolation start
		interpStart := strings.Index(raw[i:], "\\(")

		if interpStart == -1 {
			// No more interpolations, rest is literal
			if i < len(raw) {
				template.Parts = append(template.Parts, ast.TemplatePart{
					IsExpression: false,
					Literal:      raw[i:],
				})
			}
			break
		}

		// Add literal before interpolation
		if interpStart > 0 {
			template.Parts = append(template.Parts, ast.TemplatePart{
				IsExpression: false,
				Literal:      raw[i : i+interpStart],
			})
		}

		// Find matching closing paren
		exprStart := i + interpStart + 2 // skip "\("
		parenDepth := 1
		exprEnd := exprStart

		for exprEnd < len(raw) && parenDepth > 0 {
			if raw[exprEnd] == '(' {
				parenDepth++
			} else if raw[exprEnd] == ')' {
				parenDepth--
			}
			if parenDepth > 0 {
				exprEnd++
			}
		}

		// Extract and parse the expression
		exprStr := raw[exprStart:exprEnd]
		exprAST := p.parseInterpolatedExpression(exprStr)
		if exprAST != nil {
			template.Parts = append(template.Parts, ast.TemplatePart{
				IsExpression: true,
				Expression:   exprAST,
			})
		}

		// Move past the interpolation (skip past closing paren)
		i = exprEnd + 1
	}

	return template
}

func (p *Parser) parseInterpolatedExpression(exprStr string) ast.Expression {
	// Create a sub-lexer and parser for the expression
	subLexer := lexer.New(exprStr)
	subParser := New(subLexer)
	subParser.nextToken() // Initialize

	expr := subParser.parseExpression(LOWEST)

	if len(subParser.Errors()) > 0 {
		p.errors = append(p.errors, subParser.Errors()...)
		return nil
	}

	return expr
}
```

### `compiler/compiler/compiler.go` — যোগ করুন

```go
// Compile() ফাংশনের switch-এ যোগ করুন:
case *ast.StringTemplate:
	// Compile each part and concatenate
	for i, part := range node.Parts {
		if part.IsExpression {
			err := c.Compile(part.Expression)
			if err != nil {
				return err
			}
			// Convert to string if not already
			c.emit(vm.OpToString)
		} else {
			str := &object.String{Value: part.Literal}
			c.emit(vm.OpConstant, c.addConstant(str))
		}

		// Concatenate with previous parts
		if i > 0 {
			c.emit(vm.OpStringConcat)
		}
	}

	// If template is empty, push empty string
	if len(node.Parts) == 0 {
		str := &object.String{Value: ""}
		c.emit(vm.OpConstant, c.addConstant(str))
	}
