					return newError("native_print expects 1 argument, got %d", len(args))
				}
				str := fmt.Sprintf("%v", args[0].Inspect())
				cstr := C.CString(str)
				defer C.free(unsafe.Pointer(cstr))
				C.nilang_sys_print(cstr)
				return &object.Null{}
