					return newError("native_sqrt expects 1 argument, got %d", len(args))
				}

				switch arg := args[0].(type) {
				case *object.Integer:
					result := C.nilang_math_sqrt(C.double(float64(arg.Value)))
					return &object.Integer{Value: int64(result)}
				default:
					return newError("native_sqrt expects a numeric argument")
				}
			},
		},

		"native_hash": {
			Fn: func(args ...object.Object) object.Object {
				if len(args) != 1 {
					return newError("native_hash expects 1 argument, got %d", len(args))
				}

				str, ok := args[0].(*object.String)
				if !ok {
					return newError("native_hash expects a string argument")
				}

				cstr := C.CString(str.Value)
				defer C.free(unsafe.Pointer(cstr))
				hash := C.nilang_hash_fnv1a(cstr, C.size_t(len(str.Value)))
				return &object.Integer{Value: int64(hash)}
			},
		},

		"native_version": {
			Fn: func(args ...object.Object) object.Object {
				cstr := C.nilang_native_version()
				defer C.nilang_string_free(cstr)
				if cstr == nil {
					return &object.String{Value: "unknown"}
				}
				goStr := C.GoString(cstr)
				return &object.String{Value: goStr}
			},
		},
	}
}

// Helper function for creating errors
func newError(format string, a ...interface{}) *object.Error {
	return &object.Error{Message: fmt.Sprintf(format, a...)}
}
```

### `runtime/vm/Makefile`

```makefile
.PHONY: all build build-release clean test

# Detect OS
UNAME := $(shell uname -s)

# Library name based on OS
ifeq ($(UNAME),Darwin)
	LIB_NAME = libnilang_native.dylib
else
	LIB_NAME = libnilang_native.so
endif

NATIVE_DIR = native
TARGET_DIR = $(NATIVE_DIR)/target/release

all: build-release

# Build the Rust native library
build:
	cd $(NATIVE_DIR) && cargo build

build-release:
	cd $(NATIVE_DIR) && cargo build --release
	@echo "✅ Native library built: $(TARGET_DIR)/$(LIB_NAME)"

# Run Rust tests
test:
	cd $(NATIVE_DIR) && cargo test

# Clean build artifacts
clean:
	cd $(NATIVE_DIR) && cargo clean
	rm -f $(TARGET_DIR)/$(LIB_NAME)

# Build Go bridge (requires native library to be built first)
build-go: build-release
	go build -o ../../bin/nilc ../../cmd/nilc/main.go
	@echo "✅ Go compiler built"

# Build everything
build-all: build-release build-go
	@echo "✅ Full build complete"
```

