	fmt.Printf("   টার্গেট: %v\n", cfg.Targets)
	fmt.Println()

	// Step 1: Compile source code
	fmt.Print("   [1/4] কম্পাইল হচ্ছে... ")
	entryPath := cfg.GetEntryPath(projectDir)
	pipeline, err := compiler.CompileFile(entryPath)
	if err != nil {
