```go
package main

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/joysriramsarkar/alap-framework/compiler/evaluator"
	"github.com/joysriramsarkar/alap-framework/compiler/lexer"
	"github.com/joysriramsarkar/alap-framework/compiler/object"
	"github.com/joysriramsarkar/alap-framework/compiler/parser"
	"github.com/joysriramsarkar/alap-framework/pkg/config"
)

func cmdRun() {
	// Find project directory
	projectDir, err := os.Getwd()
	if err != nil {
		fmt.Fprintf(os.Stderr, "❌ কারেন্ট ডিরেক্টরি পেতে সমস্যা: %s\n", err)
		os.Exit(1)
	}

	// Load configuration
	cfg, err := config.LoadConfig(projectDir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "❌ %s\n", err)
		os.Exit(1)
	}

	// Read entry file
	entryPath := cfg.GetEntryPath(projectDir)
	source, err := os.ReadFile(entryPath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "❌ এন্ট্রি ফাইল পড়তে সমস্যা: %s\n", err)
		os.Exit(1)
	}

	// Execute using tree-walking interpreter (for development)
	env := object.NewEnvironment()

	// Register built-in functions
	registerBuiltins(env)

	// Lex and parse
	l := lexer.New(string(source))
	p := parser.New(l)
	program := p.ParseProgram()

	if len(p.Errors()) > 0 {
		fmt.Fprintf(os.Stderr, "❌ সিনট্যাক্স ত্রুটি:\n")
		for _, e := range p.Errors() {
			fmt.Fprintf(os.Stderr, "   %s\n", e)
		}
		os.Exit(1)
	}

	// Evaluate
	result := evaluator.Eval(program, env)
	if result != nil {
		if result.Type() == object.ERROR_OBJ {
			fmt.Fprintf(os.Stderr, "❌ রানটাইম ত্রুটি: %s\n", result.Inspect())
			os.Exit(1)
		}
	}
}

func registerBuiltins(env *object.Environment) {
	// Register standard built-in functions
	builtins := evaluator.GetBuiltins()
	for name, builtin := range builtins {
		env.Set(name, builtin)
	}

	// Register native built-ins if available
	nativeBuiltins := getNativeBuiltinsSafe()
	for name, builtin := range nativeBuiltins {
		env.Set(name, builtin)
	}
}

func getNativeBuiltinsSafe() map[string]*object.Builtin {
	// Try to load native builtins, return empty map if not available
	defer func() {
		if r := recover(); r != nil {
			// Native library not available, continue without it
		}
	}()

	// This would call the native bridge if available
	// For now, return empty map
	return map[string]*object.Builtin{}
}
