func cmdUninstall(cfg *nilpkg.Config) {
	if len(os.Args) < 3 {
		fmt.Println("ব্যবহার: nilpkg uninstall <package-name>")
		os.Exit(1)
	}

	name := os.Args[2]

	db, err := nilpkg.NewDatabase(cfg)
	if err != nil {
