	if !db.Has(name) {
		fmt.Fprintf(os.Stderr, "❌ প্যাকেজ ইনস্টল নেই: %s\n", name)
		os.Exit(1)
	}

	// Confirm uninstallation
	pkg, _ := db.Get(name)
	fmt.Printf("⚠️  আপনি কি নিশ্চিত '%s' v%s আনইনস্টল করতে চান? (y/n): ",
