### `pkg/registry/storage.go`

```go
package registry

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"
)

// Storage handles package data persistence
type Storage struct {
	dataDir     string
	packagesDir string
	mu          sync.RWMutex
	packages    map[string]*PackageInfo
	versions    map[string][]*VersionInfo
	users       map[string]*User
}

// NewStorage creates a new storage instance
func NewStorage(dataDir string) (*Storage, error) {
	storage := &Storage{
		dataDir:     dataDir,
		packagesDir: filepath.Join(dataDir, "packages"),
		packages:    make(map[string]*PackageInfo),
		versions:    make(map[string][]*VersionInfo),
		users:       make(map[string]*User),
	}

	// Create directories
	dirs := []string{
		dataDir,
		storage.packagesDir,
		filepath.Join(dataDir, "uploads"),
		filepath.Join(dataDir, "users"),
	}
	for _, dir := range dirs {
		if err := os.MkdirAll(dir, 0755); err != nil {
			return nil, fmt.Errorf("failed to create directory %s: %w", dir, err)
		}
	}

	// Load existing data
	if err := storage.load(); err != nil {
		// If no data exists, start fresh
		return storage, nil
	}

	return storage, nil
}

func (s *Storage) load() error {
	// Load packages index
	indexPath := filepath.Join(s.dataDir, "index.json")
	if data, err := os.ReadFile(indexPath); err == nil {
		var packages map[string]*PackageInfo
		if err := json.Unmarshal(data, &packages); err == nil {
			s.packages = packages
		}
	}

	// Load versions
	versionsPath := filepath.Join(s.dataDir, "versions.json")
	if data, err := os.ReadFile(versionsPath); err == nil {
		var versions map[string][]*VersionInfo
		if err := json.Unmarshal(data, &versions); err == nil {
			s.versions = versions
		}
	}

	// Load users
	usersPath := filepath.Join(s.dataDir, "users.json")
	if data, err := os.ReadFile(usersPath); err == nil {
		var users map[string]*User
		if err := json.Unmarshal(data, &users); err == nil {
			s.users = users
		}
	}

	return nil
}

func (s *Storage) save() error {
	// Save packages index
	indexPath := filepath.Join(s.dataDir, "index.json")
	if data, err := json.MarshalIndent(s.packages, "", "  "); err == nil {
		os.WriteFile(indexPath, data, 0644)
	}

	// Save versions
	versionsPath := filepath.Join(s.dataDir, "versions.json")
	if data, err := json.MarshalIndent(s.versions, "", "  "); err == nil {
		os.WriteFile(versionsPath, data, 0644)
	}

	// Save users
	usersPath := filepath.Join(s.dataDir, "users.json")
	if data, err := json.MarshalIndent(s.users, "", "  "); err == nil {
		os.WriteFile(usersPath, data, 0644)
	}

	return nil
}

// AddPackage adds or updates a package
func (s *Storage) AddPackage(pkg *PackageInfo) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	pkg.ID = generateID(pkg.Name, pkg.Version)
	pkg.UpdatedAt = time.Now()

	s.packages[pkg.ID] = pkg

	// Add version
	if _, exists := s.versions[pkg.Name]; !exists {
		s.versions[pkg.Name] = []*VersionInfo{}
	}

	version := &VersionInfo{
		Version:     pkg.Version,
		Checksum:    pkg.Checksum,
		Size:        pkg.Size,
		PublishedAt: pkg.PublishedAt,
		DownloadURL: pkg.DownloadURL,
	}
	s.versions[pkg.Name] = append(s.versions[pkg.Name], version)

	return s.save()
}

// GetPackage returns a package by ID
func (s *Storage) GetPackage(id string) (*PackageInfo, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	pkg, exists := s.packages[id]
	if !exists {
		return nil, fmt.Errorf("package not found: %s", id)
	}
	return pkg, nil
}

// GetPackageByName returns the latest version of a package
func (s *Storage) GetPackageByName(name string) (*PackageInfo, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	var latest *PackageInfo
	for _, pkg := range s.packages {
		if pkg.Name == name {
			if latest == nil || pkg.PublishedAt.After(latest.PublishedAt) {
				latest = pkg
			}
		}
	}

	if latest == nil {
		return nil, fmt.Errorf("package not found: %s", name)
	}
	return latest, nil
}

// SearchPackages searches for packages
func (s *Storage) SearchPackages(req *PackageSearchRequest) []*PackageInfo {
	s.mu.RLock()
	defer s.mu.RUnlock()

	var results []*PackageInfo
	query := strings.ToLower(req.Query)

	for _, pkg := range s.packages {
		if matchesSearch(pkg, query, req) {
			results = append(results, pkg)
		}
	}

	// Sort results
	sort.Slice(results, func(i, j int) bool {
		switch req.SortBy {
		case "downloads":
			return results[i].Downloads > results[j].Downloads
		case "updated":
			return results[i].UpdatedAt.After(results[j].UpdatedAt)
		default:
			return results[i].Name < results[j].Name
		}
	})

	// Pagination
	if req.Page > 0 && req.PerPage > 0 {
		start := (req.Page - 1) * req.PerPage
		end := start + req.PerPage
		if start >= len(results) {
			return []*PackageInfo{}
		}
		if end > len(results) {
			end = len(results)
		}
		results = results[start:end]
	}

	return results
}

func matchesSearch(pkg *PackageInfo, query string, req *PackageSearchRequest) bool {
	if query == "" {
		return true
	}

	// Match name
	if strings.Contains(strings.ToLower(pkg.Name), query) {
		return true
	}

	// Match description
	if strings.Contains(strings.ToLower(pkg.Description), query) {
		return true
	}

	// Match author
	if req.Author != "" && strings.Contains(strings.ToLower(pkg.Author), strings.ToLower(req.Author)) {
		return true
	}

	// Match keywords
	if req.Keyword != "" {
		for _, kw := range pkg.Keywords {
			if strings.Contains(strings.ToLower(kw), strings.ToLower(req.Keyword)) {
				return true
			}
		}
	}

	// Match targets
	if len(req.Targets) > 0 {
		for _, target := range req.Targets {
			for _, pkgTarget := range pkg.Targets {
				if target == pkgTarget {
					return true
				}
			}
		}
	}

	return false
}

// IncrementDownloads increments the download count
func (s *Storage) IncrementDownloads(packageID string) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	if pkg, exists := s.packages[packageID]; exists {
		pkg.Downloads++
		return s.save()
	}
	return fmt.Errorf("package not found: %s", packageID)
}

// GetStats returns server statistics
func (s *Storage) GetStats() *ServerStats {
	s.mu.RLock()
	defer s.mu.RUnlock()

	var totalDownloads int64
	authors := make(map[string]bool)

	for _, pkg := range s.packages {
		totalDownloads += pkg.Downloads
		authors[pkg.Author] = true
	}

	return &ServerStats{
		TotalPackages:  int64(len(s.packages)),
		TotalDownloads: totalDownloads,
		TotalAuthors:   int64(len(authors)),
		Uptime:         time.Since(startTime).String(),
		LastUpdated:    time.Now(),
	}
}

// ListAll returns all packages
func (s *Storage) ListAll() []*PackageInfo {
	s.mu.RLock()
	defer s.mu.RUnlock()

	result := make([]*PackageInfo, 0, len(s.packages))
	for _, pkg := range s.packages {
		result = append(result, pkg)
	}
	return result
}

// DeletePackage removes a package
func (s *Storage) DeletePackage(id string) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	if _, exists := s.packages[id]; !exists {
		return fmt.Errorf("package not found: %s", id)
	}

	delete(s.packages, id)
	return s.save()
}

func generateID(name, version string) string {
	return fmt.Sprintf("%s@%s", name, version)
}

var startTime = time.Now()
```

### `pkg/registry/server.go`

```go
package registry

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"time"
)

// Server represents the registry HTTP server
type Server struct {
	config  *ServerConfig
	storage *Storage
	mux     *http.ServeMux
}

// ServerConfig holds server configuration
type ServerConfig struct {
	Host        string `json:"host"`
	Port        int    `json:"port"`
	DataDir     string `json:"data_dir"`
	MaxUploadMB int    `json:"max_upload_mb"`
	EnableAuth  bool   `json:"enable_auth"`
	LogLevel    string `json:"log_level"`
}

// DefaultServerConfig returns default server configuration
func DefaultServerConfig() *ServerConfig {
	return &ServerConfig{
		Host:        "0.0.0.0",
		Port:        8080,
		DataDir:     "./registry-data",
		MaxUploadMB: 100,
		EnableAuth:  false,
		LogLevel:    "info",
	}
}

// NewServer creates a new registry server
func NewServer(config *ServerConfig) (*Server, error) {
	storage, err := NewStorage(config.DataDir)
	if err != nil {
		return nil, fmt.Errorf("failed to initialize storage: %w", err)
	}

	server := &Server{
		config:  config,
		storage: storage,
		mux:     http.NewServeMux(),
	}

	server.setupRoutes()
	return server, nil
}

func (s *Server) setupRoutes() {
	// Health check
	s.mux.HandleFunc("/health", s.handleHealth)

	// API v1 routes
	s.mux.HandleFunc("/api/v1/packages", s.handlePackages)
	s.mux.HandleFunc("/api/v1/packages/search", s.handleSearch)
	s.mux.HandleFunc("/api/v1/packages/publish", s.handlePublish)
	s.mux.HandleFunc("/api/v1/packages/stats", s.handleStats)
	s.mux.HandleFunc("/api/v1/packages/", s.handlePackageByID)

	// Download endpoint
	s.mux.HandleFunc("/api/v1/download/", s.handleDownload)

	// User management
	s.mux.HandleFunc("/api/v1/users/register", s.handleRegister)
	s.mux.HandleFunc("/api/v1/users/login", s.handleLogin)

	// Web UI (basic)
	s.mux.HandleFunc("/", s.handleWebUI)
}

// Start starts the HTTP server
func (s *Server) Start() error {
	addr := fmt.Sprintf("%s:%d", s.config.Host, s.config.Port)
	log.Printf("🚀 Nilang Registry Server starting on %s", addr)
	log.Printf("📦 Data directory: %s", s.config.DataDir)
	log.Printf("🔐 Authentication: %v", s.config.EnableAuth)

	server := &http.Server{
		Addr:         addr,
		Handler:      s.mux,
		ReadTimeout:  30 * time.Second,
		WriteTimeout: 60 * time.Second,
		IdleTimeout:  120 * time.Second,
	}

	return server.ListenAndServe()
}

// --- Handlers ---

func (s *Server) handleHealth(w http.ResponseWriter, r *http.Request) {
	s.jsonResponse(w, http.StatusOK, map[string]string{
		"status":  "healthy",
		"version": "0.1.0",
		"time":    time.Now().Format(time.RFC3339),
	})
}

func (s *Server) handlePackages(w http.ResponseWriter, r *http.Request) {
	switch r.Method {
	case http.MethodGet:
		packages := s.storage.ListAll()
		response := &PackageListResponse{
			Packages: packages,
			Total:    len(packages),
			Page:     1,
			PerPage:  len(packages),
		}
		s.jsonResponse(w, http.StatusOK, response)
	default:
		s.errorResponse(w, http.StatusMethodNotAllowed, "method not allowed")
	}
}

func (s *Server) handleSearch(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet && r.Method != http.MethodPost {
		s.errorResponse(w, http.StatusMethodNotAllowed, "method not allowed")
		return
	}

	var req PackageSearchRequest

	if r.Method == http.MethodGet {
		query := r.URL.Query()
		req.Query = query.Get("q")
		req.Author = query.Get("author")
		req.Keyword = query.Get("keyword")
		req.SortBy = query.Get("sort")
		req.Order = query.Get("order")

		if page, err := strconv.Atoi(query.Get("page")); err == nil {
			req.Page = page
		} else {
			req.Page = 1
		}
		if perPage, err := strconv.Atoi(query.Get("per_page")); err == nil {
			req.PerPage = perPage
		} else {
			req.PerPage = 20
		}
	} else {
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			s.errorResponse(w, http.StatusBadRequest, "invalid request body")
			return
		}
	}

	results := s.storage.SearchPackages(&req)
	s.jsonResponse(w, http.StatusOK, map[string]interface{}{
		"packages": results,
		"total":    len(results),
		"query":    req.Query,
	})
}

func (s *Server) handlePublish(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		s.errorResponse(w, http.StatusMethodNotAllowed, "method not allowed")
		return
	}

	// Parse multipart form
	maxUpload := int64(s.config.MaxUploadMB) * 1024 * 1024
	if err := r.ParseMultipartForm(maxUpload); err != nil {
		s.errorResponse(w, http.StatusBadRequest, "failed to parse form: "+err.Error())
		return
	}

	// Get metadata
	metadataStr := r.FormValue("metadata")
	var publishReq PublishRequest
	if err := json.Unmarshal([]byte(metadataStr), &publishReq); err != nil {
		s.errorResponse(w, http.StatusBadRequest, "invalid metadata")
		return
	}

	// Get uploaded file
	file, header, err := r.FormFile("package")
	if err != nil {
		s.errorResponse(w, http.StatusBadRequest, "package file required")
		return
	}
	defer file.Close()

	// Save uploaded file
	uploadDir := filepath.Join(s.config.DataDir, "uploads")
	filename := fmt.Sprintf("%s-%s.nilax", publishReq.Name, publishReq.Version)
	filePath := filepath.Join(uploadDir, filename)

	dst, err := os.Create(filePath)
	if err != nil {
		s.errorResponse(w, http.StatusInternalServerError, "failed to save file")
		return
	}
	defer dst.Close()

	written, err := dst.ReadFrom(file)
	if err != nil {
		s.errorResponse(w, http.StatusInternalServerError, "failed to write file")
		return
	}

	// Create package info
	pkg := &PackageInfo{
		Name:        publishReq.Name,
		Version:     publishReq.Version,
		Description: publishReq.Description,
		Author:      publishReq.Author,
		AuthorEmail: publishReq.AuthorEmail,
		License:     publishReq.License,
		DownloadURL: fmt.Sprintf("/api/v1/download/%s/%s", publishReq.Name, publishReq.Version),
		Checksum:    publishReq.Checksum,
		Size:        written,
		Targets:     publishReq.Targets,
		Dependencies: publishReq.Dependencies,
		Keywords:    publishReq.Keywords,
		PublishedAt: time.Now(),
		UpdatedAt:   time.Now(),
		Signature:   publishReq.Signature,
	}

	if err := s.storage.AddPackage(pkg); err != nil {
		s.errorResponse(w, http.StatusInternalServerError, "failed to register package")
		return
	}

	response := &PublishResponse{
		Success:     true,
		PackageID:   pkg.ID,
		DownloadURL: pkg.DownloadURL,
		Message:     fmt.Sprintf("Package %s v%s published successfully", pkg.Name, pkg.Version),
	}

	s.jsonResponse(w, http.StatusCreated, response)
}

func (s *Server) handlePackageByID(w http.ResponseWriter, r *http.Request) {
	// Extract package name from URL: /api/v1/packages/{name}
	path := r.URL.Path
	name := path[len("/api/v1/packages/"):]

	if name == "" {
		s.errorResponse(w, http.StatusBadRequest, "package name required")
		return
	}

	switch r.Method {
	case http.MethodGet:
		pkg, err := s.storage.GetPackageByName(name)
		if err != nil {
			s.errorResponse(w, http.StatusNotFound, "package not found: "+name)
			return
		}
		s.jsonResponse(w, http.StatusOK, pkg)

	case http.MethodDelete:
		if err := s.storage.DeletePackage(name); err != nil {
			s.errorResponse(w, http.StatusNotFound, "package not found: "+name)
			return
		}
		s.jsonResponse(w, http.StatusOK, map[string]string{"message": "deleted"})

	default:
		s.errorResponse(w, http.StatusMethodNotAllowed, "method not allowed")
	}
}

func (s *Server) handleDownload(w http.ResponseWriter, r *http.Request) {
	// Extract name and version from URL: /api/v1/download/{name}/{version}
	path := r.URL.Path[len("/api/v1/download/"):]
	parts := splitPath(path)

	if len(parts) < 2 {
		s.errorResponse(w, http.StatusBadRequest, "invalid download path")
		return
	}

	name := parts[0]
	version := parts[1]

	pkg, err := s.storage.GetPackageByName(name)
	if err != nil {
		s.errorResponse(w, http.StatusNotFound, "package not found")
		return
	}

	if pkg.Version != version {
		s.errorResponse(w, http.StatusNotFound, "version not found")
		return
	}

	// Increment download count
	s.storage.IncrementDownloads(pkg.ID)

	// Serve the file
	filename := fmt.Sprintf("%s-%s.nilax", name, version)
	filePath := filepath.Join(s.config.DataDir, "uploads", filename)

	if _, err := os.Stat(filePath); os.IsNotExist(err) {
		s.errorResponse(w, http.StatusNotFound, "package file not found")
		return
	}

	w.Header().Set("Content-Type", "application/octet-stream")
	w.Header().Set("Content-Disposition", fmt.Sprintf("attachment; filename=%s", filename))
	http.ServeFile(w, r, filePath)
}

func (s *Server) handleStats(w http.ResponseWriter, r *http.Request) {
	stats := s.storage.GetStats()
	s.jsonResponse(w, http.StatusOK, stats)
}

func (s *Server) handleRegister(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		s.errorResponse(w, http.StatusMethodNotAllowed, "method not allowed")
		return
	}

	var user User
	if err := json.NewDecoder(r.Body).Decode(&user); err != nil {
