// ComponentLiteral: component App { ... }
type ComponentLiteral struct {
	Token      token.Token // the 'component' token
	Name       *Identifier
	Properties []*PropertyDeclaration
	Methods    []*FunctionLiteral
	Body       *BlockStatement
}

type PropertyDeclaration struct {
	Token token.Token
	Name  *Identifier
	Type  *Identifier // Type annotation
	Value Expression  // Default value
}

func (cl *ComponentLiteral) expressionNode()      {}
func (cl *ComponentLiteral) TokenLiteral() string { return cl.Token.Literal }
func (cl *ComponentLiteral) String() string {
	var out bytes.Buffer
	out.WriteString("component ")
	out.WriteString(cl.Name.String())
	out.WriteString(" { ")
	for _, prop := range cl.Properties {
		out.WriteString(prop.String())
		out.WriteString(" ")
	}
	out.WriteString("}")
	return out.String()
}

func (pd *PropertyDeclaration) String() string {
	var out bytes.Buffer
	out.WriteString("let ")
	out.WriteString(pd.Name.String())
	if pd.Value != nil {
		out.WriteString(" = ")
		out.WriteString(pd.Value.String())
	}
	return out.String()
}

// UIElement represents a UI element in the render tree
type UIElement struct {
	Token      token.Token
	Tag        string            // "Text", "Button", "Column", etc.
	Attributes map[string]Expression
	Children   []Expression
}

func (ue *UIElement) expressionNode()      {}
func (ue *UIElement) TokenLiteral() string { return ue.Token.Literal }
func (ue *UIElement) String() string {
	var out bytes.Buffer
	out.WriteString("<")
	out.WriteString(ue.Tag)
	for key, val := range ue.Attributes {
		out.WriteString(" ")
		out.WriteString(key)
		out.WriteString("=")
		out.WriteString(val.String())
	}
	out.WriteString(">")
	for _, child := range ue.Children {
		out.WriteString(child.String())
	}
	out.WriteString("</")
	out.WriteString(ue.Tag)
	out.WriteString(">")
	return out.String()
}

// StateDeclaration: state count = 0;
type StateDeclaration struct {
	Token token.Token
	Name  *Identifier
	Value Expression
}

func (sd *StateDeclaration) statementNode()       {}
func (sd *StateDeclaration) TokenLiteral() string { return sd.Token.Literal }
func (sd *StateDeclaration) String() string {
	var out bytes.Buffer
	out.WriteString("state ")
	out.WriteString(sd.Name.String())
	out.WriteString(" = ")
	out.WriteString(sd.Value.String())
	return out.String()
}

// RenderBlock: render() { ... }
type RenderBlock struct {
	Token token.Token
	Body  *BlockStatement
}

func (rb *RenderBlock) statementNode()       {}
func (rb *RenderBlock) TokenLiteral() string { return rb.Token.Literal }
func (rb *RenderBlock) String() string {
