### `compiler/parser/parser.go` — যোগ করুন

```go
// parseStatement() switch-এ যোগ করুন:
case token.COMPONENT:
	return p.parseComponentDeclaration()

// parseExpression() prefix-এ যোগ করুন:
p.registerPrefix(token.COMPONENT, p.parseComponentExpression)

// এই ফাংশনগুলো যোগ করুন:
func (p *Parser) parseComponentDeclaration() *ast.ComponentLiteral {
	component := &ast.ComponentLiteral{Token: p.curToken}

	// Parse component name
	if !p.expectPeek(token.IDENT) {
		return nil
	}
	component.Name = &ast.Identifier{Token: p.curToken, Value: p.curToken.Literal}

	// Parse component body
	if !p.expectPeek(token.LBRACE) {
		return nil
	}

	component.Properties = []*ast.PropertyDeclaration{}
	component.Methods = []*ast.FunctionLiteral{}

	// Parse component members
	for !p.curTokenIs(token.RBRACE) && !p.curTokenIs(token.EOF) {
		switch p.curToken.Type {
		case token.LET:
			prop := p.parsePropertyDeclaration()
			if prop != nil {
				component.Properties = append(component.Properties, prop)
			}
		case token.STATE:
			prop := p.parseStateDeclaration()
			if prop != nil {
				component.Properties = append(component.Properties, prop)
			}
		case token.FN:
			method := p.parseFunctionLiteral()
			if fn, ok := method.(*ast.FunctionLiteral); ok {
				component.Methods = append(component.Methods, fn)
			}
		default:
			p.nextToken()
		}
	}

	return component
}

func (p *Parser) parsePropertyDeclaration() *ast.PropertyDeclaration {
	prop := &ast.PropertyDeclaration{Token: p.curToken}

	// Skip 'let' keyword
	p.nextToken()

	if !p.curTokenIs(token.IDENT) {
		return nil
	}

	prop.Name = &ast.Identifier{Token: p.curToken, Value: p.curToken.Literal}

	// Optional: parse type annotation
	if p.peekTokenIs(token.COLON) {
		p.nextToken() // skip ':'
		p.nextToken() // type name
		prop.Type = &ast.Identifier{Token: p.curToken, Value: p.curToken.Literal}
	}

	// Optional: parse default value
	if p.peekTokenIs(token.ASSIGN) {
		p.nextToken() // skip '='
		p.nextToken()
		prop.Value = p.parseExpression(LOWEST)
	}

	// Skip semicolon if present
	if p.peekTokenIs(token.SEMICOLON) {
		p.nextToken()
	}

	return prop
}

func (p *Parser) parseStateDeclaration() *ast.PropertyDeclaration {
	prop := &ast.PropertyDeclaration{Token: p.curToken}

	// Skip 'state' keyword
	p.nextToken()

	if !p.curTokenIs(token.IDENT) {
		return nil
	}

	prop.Name = &ast.Identifier{Token: p.curToken, Value: p.curToken.Literal}

	// Parse default value
	if p.peekTokenIs(token.ASSIGN) {
		p.nextToken() // skip '='
		p.nextToken()
		prop.Value = p.parseExpression(LOWEST)
	}

	// Skip semicolon if present
	if p.peekTokenIs(token.SEMICOLON) {
		p.nextToken()
	}

	return prop
}

func (p *Parser) parseComponentExpression() ast.Expression {
	return p.parseComponentDeclaration()
}
