// Component Declaration Example
// Alap Framework - Onuron OS

component Counter {
    state count = 0;
    let title = "My Counter";
    let step = 1;

    fn increment() {
        let count = count + step;
        emit("changed", count);
    }

    fn decrement() {
        let count = count - step;
        emit("changed", count);
    }

    fn render() {
        Column(
            Text(title),
            Text("Count: " + count),
            Row(
                Button("-", decrement),
                Button("+", increment)
            )
        )
    }
}

component App {
    let appName = "Onuron Counter";
    let version = "1.0.0";

    fn render() {
        Column(
            Text(appName + " v" + version),
            Counter(),
            Text("Powered by Nilang & Alap")
        )
    }
}

// Main execution
puts("🚀 Alap Component System Test");
puts("");

let app = App();
puts("Component created: " + app.name);

let counter = Counter();
counter.increment();
counter.increment();
counter.increment();

