	return &Discovery{
		deviceID:   deviceID,
		deviceName: deviceName,
		deviceType: deviceType,
		devices:    make(map[string]*DeviceInfo),
		listeners:  []chan *DeviceInfo{},
		stopChan:   make(chan struct{}),
	}
