// Start starts the discovery service
func (d *Discovery) Start() error {
	d.mu.Lock()
	if d.running {
		d.mu.Unlock()
		return fmt.Errorf("discovery already running")
	}
	d.running = true
	d.mu.Unlock()

	fmt.Printf("🔍 SoftBus Discovery started (Device: %s)\n", d.deviceName)

	// Start mDNS advertisement
	go d.advertise()

	// Start mDNS browsing
	go d.browse()

