## 📦 ধাপ ৩: NABC Bytecode VM (ভিত্তি)

এখন আমরা একটি **স্ট্যাক-ভিত্তিক ভার্চুয়াল মেশিন**-এর ভিত্তি তৈরি করব। এটি আপনার `onuronOS`-এ পারফরম্যান্স ১০-১০০ গুণ বাড়াবে।

### `compiler/vm/instruction.go`

```go
package vm

type OpCode byte

const (
	OpConstant OpCode = iota // Push constant onto stack
	OpPop                    // Pop top element from stack
	OpAdd                    // Addition
	OpSub                    // Subtraction
	OpMul                    // Multiplication
	OpDiv                    // Division
	OpTrue                   // Push true
	OpFalse                  // Push false
	OpEqual                  // ==
	OpNotEqual               // !=
	OpJump                   // Unconditional jump
	OpJumpNotTruthy          // Jump if top of stack is false
	OpNull                   // Push null
	OpGetGlobal              // Get global variable
	OpSetGlobal              // Set global variable
	OpGetLocal               // Get local variable
	OpSetLocal               // Set local variable
	OpCall                   // Call function
	OpReturnValue            // Return value from function
	OpReturn                 // Return null from function
	OpHalt                   // Stop execution
)

type Instruction []byte

func (ins Instruction) Opcode() OpCode {
	return OpCode(ins[0])
}

func (ins Instruction) String() string {
	switch ins.Opcode() {
	case OpConstant:
		return fmt.Sprintf("OpConstant %d", ReadUint16(ins[1:]))
	case OpAdd:
		return "OpAdd"
	case OpSub:
		return "OpSub"
	case OpMul:
		return "OpMul"
	case OpDiv:
		return "OpDiv"
	case OpPop:
		return "OpPop"
	case OpTrue:
		return "OpTrue"
	case OpFalse:
		return "OpFalse"
	case OpEqual:
		return "OpEqual"
	case OpNotEqual:
		return "OpNotEqual"
	case OpJump:
		return fmt.Sprintf("OpJump %d", ReadUint16(ins[1:]))
	case OpJumpNotTruthy:
		return fmt.Sprintf("OpJumpNotTruthy %d", ReadUint16(ins[1:]))
	case OpNull:
		return "OpNull"
	case OpHalt:
		return "OpHalt"
	default:
		return "Unknown"
	}
}

func ReadUint16(ins []byte) uint16 {
	return uint16(ins[0])<<8 | uint16(ins[1])
}
```

### `compiler/vm/code.go`

```go
package vm

import (
	"bytes"
	"encoding/binary"
	"fmt"
)

type Code []byte

func Make(op OpCode, operands ...int) []byte {
	instruction := make([]byte, 0)
	instruction = append(instruction, byte(op))

	switch op {
	case OpConstant, OpJump, OpJumpNotTruthy:
		instruction = append(instruction, uint16ToBytes(uint16(operands[0]))...)
	case OpGetGlobal, OpSetGlobal, OpGetLocal, OpSetLocal, OpCall:
		instruction = append(instruction, byte(operands[0]))
	}

	return instruction
}

func uint16ToBytes(v uint16) []byte {
	return []byte{byte(v >> 8), byte(v)}
}

// Disassemble for debugging
func Disassemble(code Code) string {
	var buf bytes.Buffer
	offset := 0
	for offset < len(code) {
		op := OpCode(code[offset])
		var inst Instruction

		switch op {
		case OpConstant, OpJump, OpJumpNotTruthy:
			inst = code[offset : offset+3]
			offset += 3
		case OpGetGlobal, OpSetGlobal, OpGetLocal, OpSetLocal, OpCall:
			inst = code[offset : offset+2]
			offset += 2
		default:
			inst = code[offset : offset+1]
			offset += 1
		}

		fmt.Fprintf(&buf, "%04d %s\n", offset-len(inst), inst.String())
	}
	return buf.String()
}
```

### `compiler/vm/vm.go` — Bytecode VM Engine

```go
package vm

import (
	"fmt"
	"github.com/joysriramsarkar/alap-framework/compiler/object"
)

const StackSize = 2048
const GlobalsSize = 65536

type VM struct {
	constants []object.Object
	stack     []object.Object
	sp        int // stack pointer (points to next free slot)
	globals   []object.Object
	code      Code
	ip        int // instruction pointer
}

func NewVM(code Code, constants []object.Object) *VM {
	return &VM{
		code:      code,
		constants: constants,
		stack:     make([]object.Object, StackSize),
		sp:        0,
		globals:   make([]object.Object, GlobalsSize),
		ip:        0,
	}
}

func (vm *VM) Run() error {
	for vm.ip < len(vm.code) {
		op := OpCode(vm.code[vm.ip])

		switch op {
		case OpConstant:
			constIndex := ReadUint16(vm.code[vm.ip+1 : vm.ip+3])
			vm.ip += 3
			err := vm.push(vm.constants[constIndex])
			if err != nil {
				return err
			}

		case OpPop:
			vm.pop()

		case OpAdd, OpSub, OpMul, OpDiv:
			err := vm.executeBinaryOperation(op)
			if err != nil {
				return err
			}

		case OpTrue:
			err := vm.push(&object.Boolean{Value: true})
			if err != nil {
				return err
			}

		case OpFalse:
			err := vm.push(&object.Boolean{Value: false})
			if err != nil {
				return err
			}

		case OpEqual, OpNotEqual:
			err := vm.executeComparison(op)
			if err != nil {
				return err
			}

		case OpJump:
			pos := int(ReadUint16(vm.code[vm.ip+1 : vm.ip+3]))
			vm.ip = pos - 1 // -1 because main loop increments ip

		case OpJumpNotTruthy:
			pos := int(ReadUint16(vm.code[vm.ip+1 : vm.ip+3]))
			vm.ip += 3

			condition := vm.pop()
			if !isTruthy(condition) {
				vm.ip = pos - 1
			}

		case OpNull:
			err := vm.push(&object.Null{})
			if err != nil {
				return err
			}

		case OpSetGlobal:
			globalIndex := int(vm.code[vm.ip+1])
			vm.ip += 2
			vm.globals[globalIndex] = vm.pop()

		case OpGetGlobal:
			globalIndex := int(vm.code[vm.ip+1])
			vm.ip += 2
			err := vm.push(vm.globals[globalIndex])
			if err != nil {
				return err
			}

		case OpHalt:
			return nil
		}

		vm.ip++
	}

	return nil
}

func (vm *VM) push(o object.Object) error {
	if vm.sp >= StackSize {
		return fmt.Errorf("stack overflow")
	}
	vm.stack[vm.sp] = o
	vm.sp++
	return nil
}

func (vm *VM) pop() object.Object {
	o := vm.stack[vm.sp-1]
	vm.sp--
	return o
}

func (vm *VM) executeBinaryOperation(op OpCode) error {
	right := vm.pop()
	left := vm.pop()

	leftType := left.Type()
	rightType := right.Type()

	switch {
	case leftType == object.INTEGER_OBJ && rightType == object.INTEGER_OBJ:
		return vm.executeBinaryIntegerOperation(op, left, right)
	case leftType == object.STRING_OBJ && rightType == object.STRING_OBJ:
		return vm.executeBinaryStringOperation(op, left, right)
	default:
		return fmt.Errorf("unsupported types for binary operation: %s %s", leftType, rightType)
	}
}

func (vm *VM) executeBinaryIntegerOperation(op OpCode, left, right object.Object) error {
	leftVal := left.(*object.Integer).Value
	rightVal := right.(*object.Integer).Value

	var result int64
	switch op {
	case OpAdd:
		result = leftVal + rightVal
	case OpSub:
		result = leftVal - rightVal
	case OpMul:
		result = leftVal * rightVal
	case OpDiv:
		result = leftVal / rightVal
	default:
		return fmt.Errorf("unknown integer operator: %d", op)
	}

	return vm.push(&object.Integer{Value: result})
}

func (vm *VM) executeBinaryStringOperation(op OpCode, left, right object.Object) error {
	if op != OpAdd {
		return fmt.Errorf("unknown string operator: %d", op)
	}
	leftVal := left.(*object.String).Value
	rightVal := right.(*object.String).Value
	return vm.push(&object.String{Value: leftVal + rightVal})
}

func (vm *VM) executeComparison(op OpCode) error {
	right := vm.pop()
	left := vm.pop()

	switch {
	case left.Type() == object.INTEGER_OBJ && right.Type() == object.INTEGER_OBJ:
		leftVal := left.(*object.Integer).Value
		rightVal := right.(*object.Integer).Value
		var result bool
		switch op {
		case OpEqual:
			result = leftVal == rightVal
		case OpNotEqual:
			result = leftVal != rightVal
		}
		return vm.push(nativeBoolToBooleanObject(result))
	default:
		return fmt.Errorf("unknown operator: %d (%s %s)", op, left.Type(), right.Type())
	}
}

func isTruthy(obj object.Object) bool {
	switch obj := obj.(type) {
	case *object.Boolean:
		return obj.Value
	case *object.Null:
		return false
	default:
		return true
	}
}

func nativeBoolToBooleanObject(input bool) *object.Boolean {
	if input {
		return &object.Boolean{Value: true}
	}
	return &object.Boolean{Value: false}
}

func (vm *VM) StackTop() object.Object {
	if vm.sp == 0 {
		return nil
	}
	return vm.stack[vm.sp-1]
}
