### `compiler/vm/vm.go` — নতুন অপকোড যোগ করুন

```go
// OpCode enum-এ যোগ করুন:
OpToString      // Convert top of stack to string
OpStringConcat  // Concatenate two strings

// Make() ফাংশনে ডিফল্ট কেসে যোগ করুন (কোনো অপারান্ড নেই):
// (ডিফল্ট কেস ইতিমধ্যে হ্যান্ডেল করবে)

// Run() ফাংশনের switch-এ যোগ করুন:
case OpToString:
	err := vm.executeToString()
	if err != nil {
		return err
	}

case OpStringConcat:
	err := vm.executeStringConcat()
	if err != nil {
		return err
	}

// এই ফাংশনগুলো যোগ করুন:
func (vm *VM) executeToString() error {
	obj := vm.pop()
	str := fmt.Sprintf("%v", obj.Inspect())
	return vm.push(&object.String{Value: str})
}

func (vm *VM) executeStringConcat() error {
	right := vm.pop()
	left := vm.pop()

	if left.Type() != object.STRING_OBJ || right.Type() != object.STRING_OBJ {
		return fmt.Errorf("string concatenation requires two strings")
	}

	leftVal := left.(*object.String).Value
	rightVal := right.(*object.String).Value
	return vm.push(&object.String{Value: leftVal + rightVal})
}
