        assert_eq!(nilang_math_add(5, 3), 8);
        assert_eq!(nilang_math_sub(5, 3), 2);
        assert_eq!(nilang_math_mul(5, 3), 15);
        assert_eq!(nilang_math_div(10, 3), 3);
        assert_eq!(nilang_math_mod(10, 3), 1);
