	env := object.NewEnvironment()

	// Register built-in functions
	registerBuiltins(env)

	// Lex and parse
	l := lexer.New(string(source))
	p := parser.New(l)
	program := p.ParseProgram()

	if len(p.Errors()) > 0 {
		fmt.Fprintf(os.Stderr, "❌ সিনট্যাক্স ত্রুটি:\n")
		for _, e := range p.Errors() {
			fmt.Fprintf(os.Stderr, "   %s\n", e)
		}
		os.Exit(1)
	}

	// Evaluate
	result := evaluator.Eval(program, env)
	if result != nil {
		if result.Type() == object.ERROR_OBJ {
			fmt.Fprintf(os.Stderr, "❌ রানটাইম ত্রুটি: %s\n", result.Inspect())
			os.Exit(1)
		}
	}
}

func registerBuiltins(env *object.Environment) {
	// Register standard built-in functions
	builtins := evaluator.GetBuiltins()
	for name, builtin := range builtins {
		env.Set(name, builtin)
	}

	// Register native built-ins if available
	nativeBuiltins := getNativeBuiltinsSafe()
	for name, builtin := range nativeBuiltins {
		env.Set(name, builtin)
	}
}

func getNativeBuiltinsSafe() map[string]*object.Builtin {
	// Try to load native builtins, return empty map if not available
	defer func() {
		if r := recover(); r != nil {
			// Native library not available, continue without it
		}
	}()

	// This would call the native bridge if available
	// For now, return empty map
	return map[string]*object.Builtin{}
}
