	fmt.Printf("📦 ফাইল: %s\n", filePath)
	fmt.Printf("🔏 চেকসাম: %s...\n", signature.Checksum[:16])
	fmt.Printf("✍️  সাইনার: %s (%s)\n", signature.SignerName, signature.SignerKeyID)
	fmt.Printf("🔐 অ্যালগরিদম: %s\n", signature.Algorithm)
	fmt.Println("═══════════════════════════════════════════")
}

