	fmt.Printf("  t=0.0: y=%.1f\n", sprite.Y)
	sprite.ApplyAnimation(bounce, 0.5)
	fmt.Printf("  t=0.5: y=%.1f\n", sprite.Y)
	sprite.ApplyAnimation(bounce, 1.0)
	fmt.Printf("  t=1.0: y=%.1f\n", sprite.Y)

	// Test 6: Easing Functions
	fmt.Println("\n--- Test 6: Easing Functions ---")
	easings := []struct {
		name string
		fn   animation.EasingFunc
	}{
		{"Linear", animation.Linear},
		{"EaseInQuad", animation.EaseInQuad},
		{"EaseOutQuad", animation.EaseOutQuad},
		{"EaseInOutQuad", animation.EaseInOutQuad},
		{"EaseInCubic", animation.EaseInCubic},
		{"EaseOutCubic", animation.EaseOutCubic},
		{"EaseInElastic", animation.EaseInElastic},
		{"EaseOutElastic", animation.EaseOutElastic},
		{"EaseInBounce", animation.EaseInBounce},
		{"EaseOutBounce", animation.EaseOutBounce},
		{"EaseInBack", animation.EaseInBack},
		{"EaseOutBack", animation.EaseOutBack},
	}

	for _, easing := range easings {
		fmt.Printf("  %-20s: t=0.25→%.3f  t=0.50→%.3f  t=0.75→%.3f\n",
			easing.name,
			easing.fn(0.25),
			easing.fn(0.50),
			easing.fn(0.75))
	}

	// Test 7: Timeline
	fmt.Println("\n--- Test 7: Timeline ---")
	timeline := engine.CreateTimeline("demo")
	timeline.Add(animation.FadeIn(0.5), 0.0)
	timeline.Add(animation.SlideIn(0.5, -100, 0), 0.5)
	timeline.Add(animation.Scale(0.3, 1.0, 1.5), 1.0)

	fmt.Printf("  Total duration: %.2fs\n", timeline.GetTotalDuration())
	fmt.Printf("  Animations: 3\n")

	// Test 8: Sprite Collision
	fmt.Println("\n--- Test 8: Sprite Collision ---")
	sprite1 := animation.NewSprite("box1").SetPosition(100, 100).SetSize(50, 50)
	sprite2 := animation.NewSprite("box2").SetPosition(120, 120).SetSize(50, 50)
	sprite3 := animation.NewSprite("box3").SetPosition(500, 500).SetSize(50, 50)

	fmt.Printf("  box1 ∩ box2: %v\n", sprite1.Intersects(sprite2))
	fmt.Printf("  box1 ∩ box3: %v\n", sprite1.Intersects(sprite3))
	fmt.Printf("  box1 → box2 distance: %.1f\n", sprite1.DistanceTo(sprite2))

	// Test 9: Complex Animation Sequence
	fmt.Println("\n--- Test 9: Complex Sequence ---")
	complexAnim := animation.NewAnimation("complex", 2.0)

	xTrack := animation.NewKeyframeTrack("x")
	xTrack.AddKeyframe(animation.NewKeyframe(0).SetValue("x", 0).SetEasing(animation.EaseOutCubic))
	xTrack.AddKeyframe(animation.NewKeyframe(0.3).SetValue("x", 200))
	xTrack.AddKeyframe(animation.NewKeyframe(0.7).SetValue("x", 200).SetEasing(animation.EaseInCubic))
	xTrack.AddKeyframe(animation.NewKeyframe(1).SetValue("x", 0))

	yTrack := animation.NewKeyframeTrack("y")
	yTrack.AddKeyframe(animation.NewKeyframe(0).SetValue("y", 0))
	yTrack.AddKeyframe(animation.NewKeyframe(0.5).SetValue("y", -100).SetEasing(animation.EaseOutQuad))
	yTrack.AddKeyframe(animation.NewKeyframe(1).SetValue("y", 0).SetEasing(animation.EaseInBounce))

	complexAnim.AddTrack(xTrack).AddTrack(yTrack)

	fmt.Printf("  t=0.0: x=%.1f, y=%.1f\n", complexAnim.GetValuesAt(0)["x"], complexAnim.GetValuesAt(0)["y"])
	fmt.Printf("  t=0.3: x=%.1f, y=%.1f\n", complexAnim.GetValuesAt(0.3)["x"], complexAnim.GetValuesAt(0.3)["y"])
	fmt.Printf("  t=0.5: x=%.1f, y=%.1f\n", complexAnim.GetValuesAt(0.5)["x"], complexAnim.GetValuesAt(0.5)["y"])
	fmt.Printf("  t=1.0: x=%.1f, y=%.1f\n", complexAnim.GetValuesAt(1)["x"], complexAnim.GetValuesAt(1)["y"])

	fmt.Println()
	fmt.Println("═══════════════════════════════════════════")
	fmt.Println("✅ Animation Engine Demo Completed!")
	fmt.Println("═══════════════════════════════════════════")

	// Keep running for a moment to show engine is active
	time.Sleep(100 * time.Millisecond)
}
