### `pkg/softbus/session.go` — সেশন ম্যানেজমেন্ট

```go
package softbus

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"sync"
	"time"
)

// SessionState represents the state of a session
type SessionState int

const (
	SessionPending SessionState = iota
	SessionActive
	SessionClosed
	SessionExpired
)

func (s SessionState) String() string {
	switch s {
	case SessionPending:
		return "PENDING"
	case SessionActive:
		return "ACTIVE"
	case SessionClosed:
		return "CLOSED"
	case SessionExpired:
		return "EXPIRED"
	default:
		return "UNKNOWN"
	}
}

// Session represents a communication session between devices
type Session struct {
	ID           string
	SourceDevice string
	DestDevice   string
	State        SessionState
	CreatedAt    time.Time
	LastActive   time.Time
	SequenceNum  uint64
	EncryptionKey []byte
	Metadata     map[string]string
}

// SessionManager manages sessions
type SessionManager struct {
	mu       sync.RWMutex
	sessions map[string]*Session
	deviceID string
	timeout  time.Duration
}

// NewSessionManager creates a new session manager
func NewSessionManager(deviceID string) *SessionManager {
	return &SessionManager{
		sessions: make(map[string]*Session),
		deviceID: deviceID,
		timeout:  5 * time.Minute,
	}
}

// CreateSession creates a new session
func (sm *SessionManager) CreateSession(destDevice string) (*Session, error) {
	sessionID, err := generateSessionID()
	if err != nil {
		return nil, err
	}

	encryptionKey := make([]byte, 32)
	if _, err := rand.Read(encryptionKey); err != nil {
		return nil, fmt.Errorf("failed to generate encryption key: %w", err)
	}

	session := &Session{
		ID:            sessionID,
		SourceDevice:  sm.deviceID,
		DestDevice:    destDevice,
		State:         SessionPending,
		CreatedAt:     time.Now(),
		LastActive:    time.Now(),
		EncryptionKey: encryptionKey,
		Metadata:      make(map[string]string),
	}

	sm.mu.Lock()
	sm.sessions[sessionID] = session
	sm.mu.Unlock()

	return session, nil
}

// GetSession returns a session by ID
func (sm *SessionManager) GetSession(sessionID string) (*Session, error) {
	sm.mu.RLock()
	defer sm.mu.RUnlock()

	session, exists := sm.sessions[sessionID]
	if !exists {
		return nil, fmt.Errorf("session not found: %s", sessionID)
	}
	return session, nil
}

// ActivateSession activates a pending session
func (sm *SessionManager) ActivateSession(sessionID string) error {
	sm.mu.Lock()
	defer sm.mu.Unlock()

	session, exists := sm.sessions[sessionID]
	if !exists {
		return fmt.Errorf("session not found: %s", sessionID)
	}

	session.State = SessionActive
	session.LastActive = time.Now()
	return nil
}

// CloseSession closes a session
func (sm *SessionManager) CloseSession(sessionID string) error {
	sm.mu.Lock()
	defer sm.mu.Unlock()

	session, exists := sm.sessions[sessionID]
	if !exists {
		return fmt.Errorf("session not found: %s", sessionID)
	}

	session.State = SessionClosed
	return nil
}

// GetNextSequence returns the next sequence number for a session
func (sm *SessionManager) GetNextSequence(sessionID string) uint64 {
	sm.mu.Lock()
	defer sm.mu.Unlock()

	if session, exists := sm.sessions[sessionID]; exists {
		session.SequenceNum++
		session.LastActive = time.Now()
		return session.SequenceNum
	}
	return 0
}

// CleanupExpired removes expired sessions
func (sm *SessionManager) CleanupExpired() int {
	sm.mu.Lock()
	defer sm.mu.Unlock()

	count := 0
	now := time.Now()
	for id, session := range sm.sessions {
		if now.Sub(session.LastActive) > sm.timeout {
			session.State = SessionExpired
			delete(sm.sessions, id)
			count++
		}
	}
	return count
}

// GetActiveSessions returns all active sessions
func (sm *SessionManager) GetActiveSessions() []*Session {
	sm.mu.RLock()
	defer sm.mu.RUnlock()

	sessions := make([]*Session, 0)
	for _, session := range sm.sessions {
		if session.State == SessionActive {
			sessions = append(sessions, session)
		}
	}
	return sessions
}

func generateSessionID() (string, error) {
	b := make([]byte, 16)
	if _, err := rand.Read(b); err != nil {
		return "", err
	}
	return hex.EncodeToString(b), nil
}
```

### `pkg/softbus/rpc.go` — রিমোট প্রসিডিউর কল

```go
package softbus

import (
	"encoding/json"
	"fmt"
	"sync"
	"time"
)

// RPCRequest represents a remote procedure call request
type RPCRequest struct {
	ID        string          `json:"id"`
	Method    string          `json:"method"`
	Params    json.RawMessage `json:"params,omitempty"`
	Timeout   time.Duration   `json:"timeout,omitempty"`
}

// RPCResponse represents a remote procedure call response
type RPCResponse struct {
	ID      string          `json:"id"`
	Result  json.RawMessage `json:"result,omitempty"`
	Error   *RPCError       `json:"error,omitempty"`
}

// RPCError represents an RPC error
type RPCError struct {
	Code    int    `json:"code"`
	Message string `json:"message"`
}

// RPCHandler is a function that handles an RPC call
type RPCHandler func(params json.RawMessage) (interface{}, error)

// RPCServer handles incoming RPC calls
type RPCServer struct {
	mu       sync.RWMutex
	handlers map[string]RPCHandler
}

// NewRPCServer creates a new RPC server
func NewRPCServer() *RPCServer {
	server := &RPCServer{
		handlers: make(map[string]RPCHandler),
	}

	// Register built-in handlers
	server.Register("ping", func(params json.RawMessage) (interface{}, error) {
		return "pong", nil
	})

	server.Register("device.info", func(params json.RawMessage) (interface{}, error) {
		return map[string]string{
			"status": "online",
		}, nil
	})

	return server
}

// Register registers an RPC handler
func (s *RPCServer) Register(method string, handler RPCHandler) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.handlers[method] = handler
}

// HandleRequest processes an incoming RPC request
func (s *RPCServer) HandleRequest(req *RPCRequest) *RPCResponse {
	s.mu.RLock()
	handler, exists := s.handlers[req.Method]
	s.mu.RUnlock()

	if !exists {
		return &RPCResponse{
			ID: req.ID,
			Error: &RPCError{
				Code:    -32601,
				Message: fmt.Sprintf("method not found: %s", req.Method),
			},
		}
	}

	result, err := handler(req.Params)
	if err != nil {
		return &RPCResponse{
			ID: req.ID,
			Error: &RPCError{
				Code:    -32000,
				Message: err.Error(),
			},
		}
	}

	resultJSON, err := json.Marshal(result)
	if err != nil {
		return &RPCResponse{
			ID: req.ID,
			Error: &RPCError{
				Code:    -32603,
				Message: "failed to marshal result",
			},
		}
	}

	return &RPCResponse{
		ID:     req.ID,
		Result: resultJSON,
	}
}

// RPCClient makes outgoing RPC calls
type RPCClient struct {
	transport *Transport
	deviceID  string
	timeout   time.Duration
}

// NewRPCClient creates a new RPC client
func NewRPCClient(transport *Transport, deviceID string) *RPCClient {
	return &RPCClient{
		transport: transport,
		deviceID:  deviceID,
		timeout:   10 * time.Second,
	}
}

// Call makes an RPC call to a remote device
func (c *RPCClient) Call(targetDevice, method string, params interface{}) (*RPCResponse, error) {
	// Generate request ID
	reqID, err := generateSessionID()
	if err != nil {
		return nil, err
	}

	// Marshal params
	var paramsJSON json.RawMessage
	if params != nil {
		paramsJSON, err = json.Marshal(params)
		if err != nil {
			return nil, fmt.Errorf("failed to marshal params: %w", err)
		}
	}

	// Create RPC request
	req := &RPCRequest{
		ID:      reqID,
		Method:  method,
		Params:  paramsJSON,
		Timeout: c.timeout,
	}

	// Create message
	msg := NewMessage(MsgRPC, c.deviceID, targetDevice)
	if err := msg.SetPayload(req); err != nil {
		return nil, err
	}

	// Send message
	if err := c.transport.Send(targetDevice, msg); err != nil {
		return nil, fmt.Errorf("failed to send RPC request: %w", err)
	}

	// In production: wait for response with timeout
	// For now, return a simulated response
	return &RPCResponse{
		ID:     reqID,
		Result: json.RawMessage(`{"status":"ok"}`),
	}, nil
}
