### `pkg/softbus/file_transfer.go` — ফাইল ট্রান্সফার

```go
package softbus

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sync"
)

const (
	FileChunkSize = 64 * 1024 // 64KB chunks
)

// FileTransferState represents the state of a file transfer
type FileTransferState int

const (
	TransferPending FileTransferState = iota
	TransferActive
	TransferComplete
	TransferFailed
	TransferCancelled
)

// FileTransfer represents a file transfer operation
type FileTransfer struct {
	ID          string
	FileName    string
	FileSize    int64
	Checksum    string
	SourceID    string
	DestID      string
	State       FileTransferState
	Progress    float64 // 0.0 - 1.0
	BytesSent   int64
	TotalChunks int
	SentChunks  int
}

// FileTransferManager manages file transfers
type FileTransferManager struct {
	mu         sync.RWMutex
	transfers  map[string]*FileTransfer
	transport  *Transport
	deviceID   string
	downloadDir string
}

// NewFileTransferManager creates a new file transfer manager
func NewFileTransferManager(transport *Transport, deviceID, downloadDir string) *FileTransferManager {
	return &FileTransferManager{
		transfers:   make(map[string]*FileTransfer),
		transport:   transport,
		deviceID:    deviceID,
		downloadDir: downloadDir,
	}
}

// SendFile initiates a file transfer to a device
func (ftm *FileTransferManager) SendFile(filePath, destDevice string) (*FileTransfer, error) {
	// Check file exists
	fileInfo, err := os.Stat(filePath)
	if err != nil {
		return nil, fmt.Errorf("file not found: %w", err)
	}

	// Calculate checksum
	checksum, err := calculateFileChecksum(filePath)
	if err != nil {
		return nil, fmt.Errorf("failed to calculate checksum: %w", err)
	}

	// Generate transfer ID
	transferID, err := generateSessionID()
	if err != nil {
		return nil, err
	}

	totalChunks := int(fileInfo.Size()/FileChunkSize) + 1

	transfer := &FileTransfer{
		ID:          transferID,
		FileName:    filepath.Base(filePath),
		FileSize:    fileInfo.Size(),
		Checksum:    checksum,
		SourceID:    ftm.deviceID,
		DestID:      destDevice,
		State:       TransferPending,
		TotalChunks: totalChunks,
	}

	ftm.mu.Lock()
	ftm.transfers[transferID] = transfer
	ftm.mu.Unlock()

	// Send file transfer request
	msg := NewMessage(MsgFileTransfer, ftm.deviceID, destDevice)
	msg.Metadata["transfer_id"] = transferID
	msg.Metadata["file_name"] = transfer.FileName
	msg.Metadata["file_size"] = fmt.Sprintf("%d", transfer.FileSize)
	msg.Metadata["checksum"] = checksum
	msg.Metadata["total_chunks"] = fmt.Sprintf("%d", totalChunks)

	if err := ftm.transport.Send(destDevice, msg); err != nil {
		transfer.State = TransferFailed
		return nil, fmt.Errorf("failed to send transfer request: %w", err)
	}

	transfer.State = TransferActive

	// In production: send file chunks
	go ftm.sendFileChunks(transfer, filePath)

	return transfer, nil
}

func (ftm *FileTransferManager) sendFileChunks(transfer *FileTransfer, filePath string) {
	file, err := os.Open(filePath)
	if err != nil {
		transfer.State = TransferFailed
		return
	}
	defer file.Close()

	buffer := make([]byte, FileChunkSize)
	chunkIndex := 0

	for {
		n, err := file.Read(buffer)
		if err == io.EOF {
			break
		}
		if err != nil {
			transfer.State = TransferFailed
			return
		}

		// Send chunk
		msg := NewMessage(MsgData, ftm.deviceID, transfer.DestID)
		msg.Metadata["transfer_id"] = transfer.ID
		msg.Metadata["chunk_index"] = fmt.Sprintf("%d", chunkIndex)
		msg.Payload = buffer[:n]

		if err := ftm.transport.Send(transfer.DestID, msg); err != nil {
			transfer.State = TransferFailed
			return
		}

		chunkIndex++
		transfer.SentChunks = chunkIndex
		transfer.BytesSent += int64(n)
		transfer.Progress = float64(transfer.BytesSent) / float64(transfer.FileSize)
	}

	transfer.State = TransferComplete
	transfer.Progress = 1.0
}

// GetTransfer returns a file transfer by ID
func (ftm *FileTransferManager) GetTransfer(transferID string) *FileTransfer {
	ftm.mu.RLock()
	defer ftm.mu.RUnlock()
	return ftm.transfers[transferID]
}

// GetActiveTransfers returns all active transfers
func (ftm *FileTransferManager) GetActiveTransfers() []*FileTransfer {
	ftm.mu.RLock()
	defer ftm.mu.RUnlock()

	transfers := make([]*FileTransfer, 0)
	for _, t := range ftm.transfers {
		if t.State == TransferActive || t.State == TransferPending {
			transfers = append(transfers, t)
		}
	}
	return transfers
}

// CancelTransfer cancels a file transfer
func (ftm *FileTransferManager) CancelTransfer(transferID string) error {
	ftm.mu.Lock()
	defer ftm.mu.Unlock()

	transfer, exists := ftm.transfers[transferID]
	if !exists {
		return fmt.Errorf("transfer not found: %s", transferID)
	}

	transfer.State = TransferCancelled
	return nil
}

func calculateFileChecksum(filePath string) (string, error) {
	file, err := os.Open(filePath)
	if err != nil {
		return "", err
	}
	defer file.Close()

	hash := sha256.New()
	if _, err := io.Copy(hash, file); err != nil {
		return "", err
	}

	return hex.EncodeToString(hash.Sum(nil)), nil
}
```

### `cmd/softbusd/main.go` — সফ্টবাট ডেমন

```go
package main

import (
	"flag"
	"fmt"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/joysriramsarkar/alap-framework/pkg/softbus"
)

func main() {
	// Parse flags
	deviceID := flag.String("id", "device-001", "Device ID")
	deviceName := flag.String("name", "Onuron Device", "Device name")
	deviceType := flag.String("type", "phone", "Device type (phone/tablet/desktop/watch)")
	port := flag.Int("port", 9000, "SoftBus port")
	version := flag.Bool("version", false, "Show version")
	flag.Parse()

	if *version {
		fmt.Println("SoftBus Daemon v0.1.0")
		fmt.Println("Nilang Distributed Communication Protocol")
		os.Exit(0)
	}

	fmt.Println("╔══════════════════════════════════════════╗")
	fmt.Println("║   🌐 SoftBus Daemon - Onuron OS          ║")
	fmt.Println("║   Distributed Device Communication       ║")
	fmt.Println("╚══════════════════════════════════════════╝")
	fmt.Println()

	// Initialize components
	fmt.Printf("📱 Device: %s (%s)\n", *deviceName, *deviceID)
	fmt.Printf("📡 Type: %s\n", *deviceType)
	fmt.Printf("🔌 Port: %d\n", *port)
	fmt.Println()

	// Step 1: Start discovery
	fmt.Print("   [1/4] Discovery service starting... ")
	discovery := softbus.NewDiscovery(*deviceID, *deviceName, *deviceType)
	if err := discovery.Start(); err != nil {
		fmt.Println("❌")
		fmt.Fprintf(os.Stderr, "❌ Discovery failed: %v\n", err)
		os.Exit(1)
	}
	fmt.Println("✅")

	// Step 2: Start transport
	fmt.Print("   [2/4] Transport layer starting... ")
	transport := softbus.NewTransport(*deviceID, nil)
	if err := transport.Listen(*port); err != nil {
		fmt.Println("❌")
		fmt.Fprintf(os.Stderr, "❌ Transport failed: %v\n", err)
		os.Exit(1)
	}
	fmt.Println("✅")

	// Step 3: Initialize session manager
	fmt.Print("   [3/4] Session manager starting... ")
	sessionMgr := softbus.NewSessionManager(*deviceID)
	_ = sessionMgr
	fmt.Println("✅")

	// Step 4: Initialize RPC server
	fmt.Print("   [4/4] RPC server starting... ")
	rpcServer := softbus.NewRPCServer()

	// Register custom RPC handlers
	rpcServer.Register("nilang.version", func(params []byte) (interface{}, error) {
		return map[string]string{
			"version":   "0.1.0",
			"compiler":  "nilc",
			"framework": "alap",
			"os":        "onuron",
		}, nil
	})

	rpcServer.Register("device.battery", func(params []byte) (interface{}, error) {
		return map[string]int{"level": 85, "charging": 0}, nil
	})

	rpcServer.Register("app.launch", func(params []byte) (interface{}, error) {
		return map[string]string{"status": "launched"}, nil
	})

	rpcServer.Register("screen.share", func(params []byte) (interface{}, error) {
		return map[string]string{"status": "sharing"}, nil
	})
	fmt.Println("✅")

	// Set up message handler
	transport.SetOnMessage(func(msg *softbus.Message) {
		fmt.Printf("📨 Message: %s from %s to %s\n", msg.Type, msg.SourceID, msg.DestID)

		switch msg.Type {
		case softbus.MsgRPC:
			var req softbus.RPCRequest
			if err := msg.GetPayload(&req); err == nil {
				resp := rpcServer.HandleRequest(&req)
				_ = resp // Would send response back
			}

		case softbus.MsgHeartbeat:
			// Handle heartbeat
			fmt.Printf("  💓 Heartbeat from %s\n", msg.SourceID)

		case softbus.MsgFileTransfer:
			fmt.Printf("  📁 File transfer request: %s\n", msg.Metadata["file_name"])
		}
	})

	// Register device found callback
	discovery.OnDeviceFound(func(device *softbus.DeviceInfo) {
		fmt.Printf("🔍 Device found: %s (%s) at %s:%d\n",
			device.DeviceName, device.DeviceType, device.IPAddress, device.Port)
	})

	// Cleanup on shutdown
	go func() {
		sigChan := make(chan os.Signal, 1)
		signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)
		<-sigChan

		fmt.Println("\n🛑 Shutting down SoftBus daemon...")
		discovery.Stop()
		transport.Stop()
		os.Exit(0)
	}()

	// Start heartbeat
	go func() {
		ticker := time.NewTicker(30 * time.Second)
		defer ticker.Stop()

		for range ticker.C {
			heartbeat := &softbus.Heartbeat{
				DeviceID:  *deviceID,
				Timestamp: time.Now().UnixMilli(),
				Load:      0.1,
				Battery:   85,
			}
			_ = heartbeat // Would broadcast to connected devices
		}
	}()

	// Session cleanup
	go func() {
		ticker := time.NewTicker(1 * time.Minute)
		defer ticker.Stop()

		for range ticker.C {
			expired := sessionMgr.CleanupExpired()
			if expired > 0 {
				fmt.Printf("🧹 Cleaned up %d expired sessions\n", expired)
			}
		}
	}()

	fmt.Println()
	fmt.Println("═══════════════════════════════════════════")
	fmt.Println("✅ SoftBus Daemon is running!")
	fmt.Printf("📡 Listening on port %d\n", *port)
	fmt.Println("🔍 Discovering nearby devices...")
	fmt.Println("Press Ctrl+C to stop")
	fmt.Println("═══════════════════════════════════════════")

	// Keep running
	select {}
}
